INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u3-C1','kor',2,2,'u3',1,'설명하는 대상과 특징 알기 — 물건을 설명할 때 특징 하나(동그란 모양)만 말하면 비슷한 물건이 많아 알아맞히기 어려우므로, 모양·색깔·쓰임새처럼 대상에 알맞은 특징을 여러 가지 함께 말하기(유정이 그림·세 고개 놀이)',ARRAY['2국03-03']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u3-C2','kor',2,2,'u3',3,'제목을 보고 글 내용 짐작하기 — 글을 읽기 전에 제목·사진·그림을 보고 무엇에 대한 글일지 짐작하고, 다 읽은 뒤 짐작과 맞는지 확인하기',ARRAY['2국02-03']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u3-C3','kor',2,2,'u3',3,'글을 읽고 내용 파악하기 — 「진심으로 사과하는 법을 알아 둬」를 읽고 사과해야 하는 까닭, 정중하게 묻기, 변명하지 않기처럼 글에 나온 내용을 근거로 물음에 답하기',ARRAY['2국02-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u3-C4','kor',2,2,'u3',3,'중심 내용을 찾는 방법 — 제목을 보고 무슨 내용일지 짐작하고, 글쓴이가 하고 싶은 말이 무엇인지 찾고, 글쓴이가 그렇게 말한 까닭을 찾기. 중요한 문장은 덩어리마다 한두 개만 고르고 까닭을 말하며 친구와 견주기',ARRAY['2국02-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u3-C5','kor',2,2,'u3',5,'설명하는 글을 읽고 내용 간추리기 — 「빗자루」·「글자」처럼 설명하는 글에서 대상이 무엇인지 찾고, 쓰임새·만드는 방법·이름·놀이처럼 덩어리마다 중요한 내용을 찾아 이어서 짧게 간추리기',ARRAY['2국02-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u3-C6','kor',2,2,'u3',5,'낱말의 뜻과 차례를 알려 주는 말 — 묶어/풀어, 질겨져/연해져, 가지런히/들쭉날쭉처럼 뜻이 반대인 낱말을 알고, 먼저·그런 다음에·그러고는·이제처럼 차례를 알려 주는 말 살피기',ARRAY['2국02-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u3-C7','kor',2,2,'u3',7,'설명하는 글을 쓰는 방법 — 설명하려는 대상을 정하고, 대상의 특징을 생각하고, 듣거나 읽는 사람이 궁금해할 내용을 생각하기(「여러 가지 옷차림」: 장소·하는 일·날씨에 따라). 좋다·나쁘다 같은 내 생각보다 누구나 알 수 있는 사실을 쓰기',ARRAY['2국03-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u3-C8','kor',2,2,'u3',7,'겹받침이 있는 낱말 바르게 쓰기 — 얇고·짧은·없잖아·않는·긁어내·삶아요·핥아서·잃어버렸어요처럼 소리와 쓰는 법이 다른 겹받침 낱말을 바르게 쓰고, 받침이 달라지면 뜻이 달라짐(삶아요/살아요) 알기',ARRAY['2국03-03']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u3-C9','kor',2,2,'u3',9,'좋아하는 사물을 설명하는 글 쓰고 점검하기 — 구체적인 사물을 대상으로 정해 맛·색·모양·크기·사용 방법·주의할 점 등 특징을 문장으로 쓰고, 특징이 잘 드러나는지·자세한지·친구가 궁금해할 내용이 있는지 점검해 고쳐 쓰고 수수께끼로 나누기',ARRAY['2국03-04']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u3-C10','kor',2,2,'u3',11,'놀이 방법을 설명하는 글 쓰기 — 필요한 사람 수·준비물·놀이 장소·놀이 규칙·주의할 점을 넣고, 숫자나 그림 메모로 차례를 나타내 친구가 따라 할 수 있게 쓰고, 놀이해 본 뒤 고칠 점을 나누기(책 표지 낱말 놀이·신호등 다섯 고개)',ARRAY['2국03-03']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u3-X01','kor',2,'u3',ARRAY['K2-2-u3-C1','K2-2-u3-C7','K2-2-u3-C9']::text[],'특징 하나만 말해도 대상을 알 수 있다고 여긴다(「동그란 모양이에요.」만 말하기)','「그 말만 듣고 떠오르는 물건이 몇 개일까?」 — 둘 이상이면 특징을 하나 더 보태기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u3-X02','kor',2,'u3',ARRAY['K2-2-u3-C1','K2-2-u3-C7','K2-2-u3-C9']::text[],'대상과 상관없는 내용(내 기분·내 가족·그날 있었던 일)을 특징으로 넣는다','문장 앞에 대상 이름을 붙여 읽어 보기 — 「포도는 동생이 일곱 살입니다」처럼 어색하면 빼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u3-X03','kor',2,'u3',ARRAY['K2-2-u3-C2']::text[],'제목을 보지 않고 짐작하거나 제목 낱말의 다른 뜻으로 엉뚱하게 짐작한다(사과 → 과일)','제목 낱말에 동그라미 치고 「이 글에서는 어떤 뜻일까?」 그림·사진과 함께 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u3-X04','kor',2,'u3',ARRAY['K2-2-u3-C3','K2-2-u3-C5']::text[],'글에 나온 내용이 아니라 자기 경험이나 짐작으로 답을 고른다','답을 고른 뒤 「글 어디에 있지?」 하고 손가락으로 그 줄을 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u3-X05','kor',2,'u3',ARRAY['K2-2-u3-C4','K2-2-u3-C5']::text[],'중심 내용을 문장 위치(첫 문장)로만 찾거나 모든 문장에 밑줄을 긋는다','덩어리마다 「이 덩어리는 무엇 이야기?」 한마디로 말한 뒤, 그 말에 가장 가까운 문장 하나만 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u3-X06','kor',2,'u3',ARRAY['K2-2-u3-C4']::text[],'중심 내용을 찾는 방법(제목 → 하고 싶은 말 → 까닭)을 헷갈리거나 글자 수·글쓴이 이름 같은 것을 방법으로 여긴다','제목 · 하고 싶은 말 · 까닭 세 손가락으로 차례대로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u3-X07','kor',2,'u3',ARRAY['K2-2-u3-C5']::text[],'작은 내용(칼의 모양·손가락 굵기·마법사 이야기)을 글의 중심 내용으로 고른다','「이게 빠지면 빗자루를 모르게 될까?」 — 빠져도 괜찮으면 작은 내용') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u3-X08','kor',2,'u3',ARRAY['K2-2-u3-C3']::text[],'사과할 때 변명하거나 상대 잘못을 따지는 말도 괜찮은 사과라고 여긴다','「하지만」, 「너도」가 들어갔는지 찾아보기 — 들어가면 사과가 아니라 다툼이 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u3-X09','kor',2,'u3',ARRAY['K2-2-u3-C6']::text[],'뜻이 반대인 낱말을 비슷한 낱말과 헷갈린다(질겨져 ↔ 억세져)','두 낱말을 같은 문장에 넣어 읽어 보기 — 뜻이 거꾸로 되면 반대말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u3-X10','kor',2,'u3',ARRAY['K2-2-u3-C5','K2-2-u3-C6','K2-2-u3-C10']::text[],'차례를 알려 주는 말(먼저·그런 다음에·이제)을 놓치고 순서를 뒤섞는다','차례 말에 번호를 붙여 ①②③으로 다시 늘어놓기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u3-X11','kor',2,'u3',ARRAY['K2-2-u3-C7','K2-2-u3-C9']::text[],'설명하는 글에 사람(친구 생김새)을 대상으로 하거나 좋다·예쁘다·촌스럽다 같은 내 판단을 넣는다','「누가 읽어도 맞다고 할까?」 — 사람마다 다르게 느끼면 설명이 아니라 내 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u3-X12','kor',2,'u3',ARRAY['K2-2-u3-C7','K2-2-u3-C9']::text[],'읽는 사람이 궁금해할 내용을 생각하지 않고 내가 쓰고 싶은 것만 쓴다','친구에게 「무엇이 궁금해?」 묻고 나온 질문을 글에 하나 넣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u3-X13','kor',2,'u3',ARRAY['K2-2-u3-C8']::text[],'겹받침 낱말을 소리 나는 대로 쓰거나(짤븐·할타서·이러버렸어요) 받침 하나를 빠뜨린다(살아요 ↔ 삶아요)','낱말 뒤에 「~아요/~어요」를 붙여 천천히 읽기 — 짧아요·핥아요·삶아요에서 두 받침이 다 들려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u3-X14','kor',2,'u3',ARRAY['K2-2-u3-C10']::text[],'놀이 설명에 필요한 것(사람 수·준비물·규칙·순서·주의할 점)을 빼먹거나 놀이와 상관없는 것을 쓴다','「처음 하는 친구가 이 글만 보고 놀 수 있을까?」 — 막히는 곳에 빠진 것을 채우기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u3-X15','kor',2,'u3',ARRAY['K2-2-u3-C7','K2-2-u3-C9']::text[],'대상과 특징을 문장으로 잇지 못하고 낱말만 늘어놓는다(「떡볶이 매콤.」)','「○○의 △△은/는 □□합니다.」 틀에 넣어 한 문장으로 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L01_basic#1','kor',2,2,'u3','L01','g2_2_kor_u3_L01_basic','lesson_basic','K2-2-u3-C1',1,'mc','auto','『국어』 71쪽 생각 열기 — 책 읽는 친구가 「이 글에서는 무엇을 설명하고 있을까?」 하고 생각해요. 이 친구가 알고 싶은 것은?',ARRAY['K2-2-u3-X04','K2-2-u3-X06']::text[],false,'{"seq":1,"concept":"K2-2-u3-C1","difficulty":1,"kind":"mc","stem":"『국어』 71쪽 생각 열기 — 책 읽는 친구가 「이 글에서는 무엇을 설명하고 있을까?」 하고 생각해요. 이 친구가 알고 싶은 것은?","options":[{"t":"글이 설명하는 대상","correct":true},{"t":"글을 쓴 날짜","mis":"K2-2-u3-X04"},{"t":"글의 글자 수","mis":"K2-2-u3-X06"}],"explanation":["무엇을 설명하는지 알고 싶어요.","그것을 「대상」이라고 해요.","71쪽이에요."],"asset":{"type":"scene","icon":"📖🧒✏️👧🚲🎵","text":"『국어』 71쪽 — 한 친구는 책을 읽고, 두 친구는 자전거·음표를 떠올리며 설명하는 글을 써요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L01_basic#2','kor',2,2,'u3','L01','g2_2_kor_u3_L01_basic','lesson_basic','K2-2-u3-C1',1,'mc','auto','『국어』 73쪽 2번 (1) — 유정이가 설명하려는 물건은 어떤 모양인가요?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":2,"concept":"K2-2-u3-C1","difficulty":1,"kind":"mc","stem":"『국어』 73쪽 2번 (1) — 유정이가 설명하려는 물건은 어떤 모양인가요?","options":[{"t":"동그란 모양","correct":true},{"t":"네모난 모양","mis":"K2-2-u3-X04"},{"t":"세모난 모양","mis":"K2-2-u3-X04"}],"explanation":["동그란 모양이에요.","유정이의 말에 있어요.","73쪽 예시 답안이에요."],"asset":{"type":"speech","turns":[{"who":"유정","text":"이 물건은 동그란 모양입니다."},{"who":"친구들","text":"(저마다 다른 물건을 떠올려요) 시계? 농구공? 물병?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
