INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L01_challenge#5','kor',2,2,'u3','L01','g2_2_kor_u3_L01_challenge','lesson_challenge','K2-2-u3-C1',3,'mc','auto','지우개를 설명하는 특징으로 알맞지 않은 것은?',ARRAY['K2-2-u3-X01']::text[],false,'{"seq":5,"concept":"K2-2-u3-C1","difficulty":3,"kind":"mc","stem":"지우개를 설명하는 특징으로 알맞지 않은 것은?","options":[{"t":"어제 짝과 함께 본 만화","correct":true},{"t":"말랑말랑해요","mis":"K2-2-u3-X01"},{"t":"연필 글씨를 지워요","mis":"K2-2-u3-X01"}],"explanation":["만화는 지우개와 상관없어요.","특징만 골라요.","지도서 153쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L01_challenge#6','kor',2,2,'u3','L01','g2_2_kor_u3_L01_challenge','lesson_challenge','K2-2-u3-C1',3,'mc','auto','설명을 듣고 「시계? 물병?」처럼 헷갈릴 때 듣는 사람이 할 수 있는 말은?',ARRAY['K2-2-u3-X12','K2-2-u3-X04']::text[],false,'{"seq":6,"concept":"K2-2-u3-C1","difficulty":3,"kind":"mc","stem":"설명을 듣고 「시계? 물병?」처럼 헷갈릴 때 듣는 사람이 할 수 있는 말은?","options":[{"t":"「색깔은 어때요?」 하고 궁금한 것을 물어요","correct":true},{"t":"「몰라요.」 하고 그만둬요","mis":"K2-2-u3-X12"},{"t":"아무 물건이나 말해요","mis":"K2-2-u3-X04"}],"explanation":["궁금한 것을 물어요.","특징이 하나 더 생겨요.","지도서 137쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L01_challenge#7','kor',2,2,'u3','L01','g2_2_kor_u3_L01_challenge','lesson_challenge','K2-2-u3-C1',3,'ox','auto','하나의 물건도 여러 가지로 설명할 수 있어요.',ARRAY['K2-2-u3-X01']::text[],false,'{"seq":7,"concept":"K2-2-u3-C1","difficulty":3,"kind":"ox","stem":"하나의 물건도 여러 가지로 설명할 수 있어요.","answer":"O","reason_options":[{"t":"모양·색깔·쓰임새처럼 물건에는 여러 특징이 있으니까","correct":true},{"t":"물건마다 설명은 하나뿐이니까","mis":"K2-2-u3-X01"}],"mis":"K2-2-u3-X01","explanation":["여러 가지로 설명해요.","지도서 137쪽이에요.","다르게 설명해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L01_challenge#8','kor',2,2,'u3','L01','g2_2_kor_u3_L01_challenge','lesson_challenge','K2-2-u3-C1',4,'sa','auto','『국어』 86쪽 — 글에서 설명하는 물건이나 사람 따위를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u3-C1","difficulty":4,"kind":"sa","stem":"『국어』 86쪽 — 글에서 설명하는 물건이나 사람 따위를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["대상"],"explanation":["대상이에요.","86쪽 도움말이에요.","무엇을 설명하는지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L01_challenge#9','kor',2,2,'u3','L01','g2_2_kor_u3_L01_challenge','lesson_challenge','K2-2-u3-C1',4,'essay','teacher','교실에 있는 물건 하나를 골라, 이름은 쓰지 말고 친구가 알아맞힐 수 있게 특징을 세 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u3-C1","difficulty":4,"kind":"essay","stem":"교실에 있는 물건 하나를 골라, 이름은 쓰지 말고 친구가 알아맞힐 수 있게 특징을 세 가지 쓰세요.","answer_guide":{"answer":"예: 네모난 모양이에요. / 숫자와 글자가 쓰여 있어요. / 교실 벽에 걸려 있고 날짜를 알려 줘요. (달력)","scoring_points":["특징이 세 가지예요","대상에 알맞은 특징이에요","이름을 쓰지 않았어요"]},"explanation":["물건을 자세히 살펴요.","특징을 여러 가지 써요.","73쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L01_challenge#10','kor',2,2,'u3','L01','g2_2_kor_u3_L01_challenge','lesson_challenge','K2-2-u3-C1',4,'essay','teacher','유정이의 「이 물건은 동그란 모양입니다.」에 이어, 친구들이 「시계」를 떠올릴 수 있게 설명하는 문장을 두 개 더 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u3-C1","difficulty":4,"kind":"essay","stem":"유정이의 「이 물건은 동그란 모양입니다.」에 이어, 친구들이 「시계」를 떠올릴 수 있게 설명하는 문장을 두 개 더 쓰세요.","answer_guide":{"answer":"예: 얼굴에 숫자가 있습니다. / 시간을 알려 줍니다.","scoring_points":["시계에 알맞은 특징이에요","문장이 두 개예요"]},"explanation":["다른 특징을 보태요.","모양 말고도 있어요.","72~73쪽이에요."],"asset":{"type":"speech","turns":[{"who":"유정","text":"이 물건은 동그란 모양입니다."},{"who":"친구들","text":"(저마다 다른 물건을 떠올려요) 시계? 농구공? 물병?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L03_basic#1','kor',2,2,'u3','L03','g2_2_kor_u3_L03_basic','lesson_basic','K2-2-u3-C2',1,'mc','auto','『국어』 74쪽 — 제목 「진심으로 사과하는 법을 알아 둬」를 보고 짐작할 수 있는 내용은?',ARRAY['K2-2-u3-X03']::text[],false,'{"seq":1,"concept":"K2-2-u3-C2","difficulty":1,"kind":"mc","stem":"『국어』 74쪽 — 제목 「진심으로 사과하는 법을 알아 둬」를 보고 짐작할 수 있는 내용은?","options":[{"t":"사과를 잘하는 방법","correct":true},{"t":"사과를 맛있게 먹는 방법","mis":"K2-2-u3-X03"},{"t":"재미있는 놀이 방법","mis":"K2-2-u3-X03"}],"explanation":["제목에 「사과하는 법」이 있어요.","글쓴이가 알려 주려는 것이에요.","76쪽 3번 (1)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L03_basic#2','kor',2,2,'u3','L03','g2_2_kor_u3_L03_basic','lesson_basic','K2-2-u3-C3',1,'mc','auto','『국어』 76쪽 2번 (1) — 잘못을 했을 때 사과해야 하는 까닭은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":2,"concept":"K2-2-u3-C3","difficulty":1,"kind":"mc","stem":"『국어』 76쪽 2번 (1) — 잘못을 했을 때 사과해야 하는 까닭은?","options":[{"t":"마음속으로만 잘못했다고 생각하면 상대가 알 수 없기 때문이에요","correct":true},{"t":"사과하면 선물을 받기 때문이에요","mis":"K2-2-u3-X04"},{"t":"혼나지 않으려고요","mis":"K2-2-u3-X04"}],"explanation":["말해야 마음이 전해져요.","글에 나와 있어요.","76쪽 예시 답안이에요."],"asset":{"type":"passage","lines":["잘못했을 때는 상대에게 꼭 사과해야 해요.","마음속으로만 생각하면 상대는 알 수 없어요.","왜 미안한지 말하고, 다시는 그러지 않겠다고 약속해요.","받아 줄지는 상처받은 상대가 정해요.","그래서 「내 사과를 받아 줄래?」 하고 정중하게 물어봐요.","상대 잘못을 따지거나 「하지만…….」 하고 변명하지 않아요.","깨끗하게 잘못을 인정하고 진심으로 사과해요."],"title":"『국어』 74~75쪽 「진심으로 사과하는 법을 알아 둬」(박현숙) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L03_basic#3','kor',2,2,'u3','L03','g2_2_kor_u3_L03_basic','lesson_basic','K2-2-u3-C3',1,'mc','auto','『국어』 76쪽 2번 (2) — 사과를 받아 주는 상대에게 뭐라고 물어봐야 할까요?',ARRAY['K2-2-u3-X08']::text[],false,'{"seq":3,"concept":"K2-2-u3-C3","difficulty":1,"kind":"mc","stem":"『국어』 76쪽 2번 (2) — 사과를 받아 주는 상대에게 뭐라고 물어봐야 할까요?","options":[{"t":"「내 사과를 받아 줄래?」","correct":true},{"t":"「미안하다고 했잖아, 됐지?」","mis":"K2-2-u3-X08"},{"t":"「빨리 받아 줘.」","mis":"K2-2-u3-X08"}],"explanation":["정중하게 물어요.","받아 줄지는 상대가 정해요.","76쪽 예시 답안이에요."],"asset":{"type":"passage","lines":["잘못했을 때는 상대에게 꼭 사과해야 해요.","마음속으로만 생각하면 상대는 알 수 없어요.","왜 미안한지 말하고, 다시는 그러지 않겠다고 약속해요.","받아 줄지는 상처받은 상대가 정해요.","그래서 「내 사과를 받아 줄래?」 하고 정중하게 물어봐요.","상대 잘못을 따지거나 「하지만…….」 하고 변명하지 않아요.","깨끗하게 잘못을 인정하고 진심으로 사과해요."],"title":"『국어』 74~75쪽 「진심으로 사과하는 법을 알아 둬」(박현숙) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L03_basic#4','kor',2,2,'u3','L03','g2_2_kor_u3_L03_basic','lesson_basic','K2-2-u3-C4',1,'mc','auto','『국어』 77쪽 4번 — 무슨 내용일지 짐작하려고 먼저 보는 것은?',ARRAY['K2-2-u3-X06']::text[],false,'{"seq":4,"concept":"K2-2-u3-C4","difficulty":1,"kind":"mc","stem":"『국어』 77쪽 4번 — 무슨 내용일지 짐작하려고 먼저 보는 것은?","options":[{"t":"제목","correct":true},{"t":"글쓴이 이름","mis":"K2-2-u3-X06"},{"t":"글자 수","mis":"K2-2-u3-X06"}],"explanation":["제목을 봐요.","77쪽 4번이에요.","짐작하고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L03_basic#5','kor',2,2,'u3','L03','g2_2_kor_u3_L03_basic','lesson_basic','K2-2-u3-C3',2,'mc','auto','『국어』 76쪽 2번 (3) — 사과할 때 변명하는 것이 좋지 않은 까닭은?',ARRAY['K2-2-u3-X04','K2-2-u3-X08']::text[],false,'{"seq":5,"concept":"K2-2-u3-C3","difficulty":2,"kind":"mc","stem":"『국어』 76쪽 2번 (3) — 사과할 때 변명하는 것이 좋지 않은 까닭은?","options":[{"t":"변명하다 보면 상대를 탓하게 되기 때문이에요","correct":true},{"t":"변명은 말이 너무 짧기 때문이에요","mis":"K2-2-u3-X04"},{"t":"변명하면 사과가 빨리 끝나기 때문이에요","mis":"K2-2-u3-X08"}],"explanation":["상대를 탓하게 돼요.","다시 다툴 수 있어요.","76쪽 예시 답안이에요."],"asset":{"type":"passage","lines":["잘못했을 때는 상대에게 꼭 사과해야 해요.","마음속으로만 생각하면 상대는 알 수 없어요.","왜 미안한지 말하고, 다시는 그러지 않겠다고 약속해요.","받아 줄지는 상처받은 상대가 정해요.","그래서 「내 사과를 받아 줄래?」 하고 정중하게 물어봐요.","상대 잘못을 따지거나 「하지만…….」 하고 변명하지 않아요.","깨끗하게 잘못을 인정하고 진심으로 사과해요."],"title":"『국어』 74~75쪽 「진심으로 사과하는 법을 알아 둬」(박현숙) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L03_basic#6','kor',2,2,'u3','L03','g2_2_kor_u3_L03_basic','lesson_basic','K2-2-u3-C3',2,'match','auto','『국어』 77쪽 3번 (3) — 문장과 빈칸에 들어갈 말을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K2-2-u3-C3","difficulty":2,"kind":"match","stem":"『국어』 77쪽 3번 (3) — 문장과 빈칸에 들어갈 말을 이어 보세요.","pairs":[{"l":"잘못을 했을 때에는 상대에게 꼭 ___하고 미안한 까닭을 말한다.","r":"사과"},{"l":"「내 사과를 받아 줄래?」라고 ___하게 물어본다.","r":"정중"},{"l":"자신의 잘못을 깨끗하게 ___하고 진심으로 사과한다.","r":"인정"}],"mis":"K2-2-u3-X04","explanation":["사과 · 정중 · 인정이에요.","77쪽 예시 답안이에요.","보기에서 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L03_basic#7','kor',2,2,'u3','L03','g2_2_kor_u3_L03_basic','lesson_basic','K2-2-u3-C4',2,'match','auto','『국어』 77쪽 4번 — 중심 내용을 찾는 방법과 들어갈 말을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K2-2-u3-C4","difficulty":2,"kind":"match","stem":"『국어』 77쪽 4번 — 중심 내용을 찾는 방법과 들어갈 말을 이어 보세요.","pairs":[{"l":"___을 보고 무슨 내용일지 짐작한다.","r":"제목"},{"l":"글쓴이가 ___이 무엇인지 찾아본다.","r":"하고 싶은 말"},{"l":"글쓴이가 그렇게 말한 ___을 찾는다.","r":"까닭"}],"mis":"K2-2-u3-X06","explanation":["제목 · 하고 싶은 말 · 까닭이에요.","77쪽 예시 답안이에요.","차례대로 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L03_basic#8','kor',2,2,'u3','L03','g2_2_kor_u3_L03_basic','lesson_basic','K2-2-u3-C3',2,'ox','auto','「나도 잘못했지만 너도 잘못했어.」는 진심이 담긴 사과예요.',ARRAY['K2-2-u3-X08']::text[],false,'{"seq":8,"concept":"K2-2-u3-C3","difficulty":2,"kind":"ox","stem":"「나도 잘못했지만 너도 잘못했어.」는 진심이 담긴 사과예요.","answer":"X","reason_options":[{"t":"사과하면서 따지면 다시 다툴 수 있으니까","correct":true},{"t":"둘 다 말해야 공평하니까","mis":"K2-2-u3-X08"}],"mis":"K2-2-u3-X08","explanation":["따지면 사과가 아니에요.","글 뒷부분에 있어요.","75쪽이에요."],"asset":{"type":"passage","lines":["잘못했을 때는 상대에게 꼭 사과해야 해요.","마음속으로만 생각하면 상대는 알 수 없어요.","왜 미안한지 말하고, 다시는 그러지 않겠다고 약속해요.","받아 줄지는 상처받은 상대가 정해요.","그래서 「내 사과를 받아 줄래?」 하고 정중하게 물어봐요.","상대 잘못을 따지거나 「하지만…….」 하고 변명하지 않아요.","깨끗하게 잘못을 인정하고 진심으로 사과해요."],"title":"『국어』 74~75쪽 「진심으로 사과하는 법을 알아 둬」(박현숙) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
