INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L03_challenge#4','kor',2,2,'u3','L03','g2_2_kor_u3_L03_challenge','lesson_challenge','K2-2-u3-C3',3,'mc','auto','「미안해. 하지만…….」 하고 사과하면 어떻게 될까요?',ARRAY['K2-2-u3-X08']::text[],false,'{"seq":4,"concept":"K2-2-u3-C3","difficulty":3,"kind":"mc","stem":"「미안해. 하지만…….」 하고 사과하면 어떻게 될까요?","options":[{"t":"변명이 되어 상대가 더 화날 수 있어요","correct":true},{"t":"사과가 더 진심으로 들려요","mis":"K2-2-u3-X08"},{"t":"상대가 바로 웃어요","mis":"K2-2-u3-X08"}],"explanation":["변명은 탓이 돼요.","75쪽이에요.","딱 사과만 해요."],"asset":{"type":"passage","lines":["잘못했을 때는 상대에게 꼭 사과해야 해요.","마음속으로만 생각하면 상대는 알 수 없어요.","왜 미안한지 말하고, 다시는 그러지 않겠다고 약속해요.","받아 줄지는 상처받은 상대가 정해요.","그래서 「내 사과를 받아 줄래?」 하고 정중하게 물어봐요.","상대 잘못을 따지거나 「하지만…….」 하고 변명하지 않아요.","깨끗하게 잘못을 인정하고 진심으로 사과해요."],"title":"『국어』 74~75쪽 「진심으로 사과하는 법을 알아 둬」(박현숙) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L03_challenge#5','kor',2,2,'u3','L03','g2_2_kor_u3_L03_challenge','lesson_challenge','K2-2-u3-C4',3,'mc','auto','친구가 중요한 문장으로 나와 다른 문장을 골랐어요. 알맞게 하는 것은?',ARRAY['K2-2-u3-X05']::text[],false,'{"seq":5,"concept":"K2-2-u3-C4","difficulty":3,"kind":"mc","stem":"친구가 중요한 문장으로 나와 다른 문장을 골랐어요. 알맞게 하는 것은?","options":[{"t":"서로 그렇게 생각한 까닭을 말하고 견주어 봐요","correct":true},{"t":"내 것만 맞다고 말해요","mis":"K2-2-u3-X05"},{"t":"친구 것을 지우고 내 것을 써요","mis":"K2-2-u3-X05"}],"explanation":["까닭을 나눠요.","지도서 140쪽이에요.","생각이 넓어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L03_challenge#6','kor',2,2,'u3','L03','g2_2_kor_u3_L03_challenge','lesson_challenge','K2-2-u3-C4',3,'ox','auto','중심 내용은 언제나 글의 첫 문장이에요.',ARRAY['K2-2-u3-X05']::text[],false,'{"seq":6,"concept":"K2-2-u3-C4","difficulty":3,"kind":"ox","stem":"중심 내용은 언제나 글의 첫 문장이에요.","answer":"X","reason_options":[{"t":"글쓴이가 하고 싶은 말은 글 여러 곳에 나올 수 있으니까","correct":true},{"t":"첫 문장이 가장 앞에 있으니까","mis":"K2-2-u3-X05"}],"mis":"K2-2-u3-X05","explanation":["위치로 찾지 않아요.","내용으로 찾아요.","지도서 135쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L03_challenge#7','kor',2,2,'u3','L03','g2_2_kor_u3_L03_challenge','lesson_challenge','K2-2-u3-C3',3,'mc','auto','사과하는 사람이 다시는 그런 일을 하지 않겠다고 말하는 것은 무엇인가요?',ARRAY['K2-2-u3-X08','K2-2-u3-X04']::text[],false,'{"seq":7,"concept":"K2-2-u3-C3","difficulty":3,"kind":"mc","stem":"사과하는 사람이 다시는 그런 일을 하지 않겠다고 말하는 것은 무엇인가요?","options":[{"t":"약속","correct":true},{"t":"변명","mis":"K2-2-u3-X08"},{"t":"칭찬","mis":"K2-2-u3-X04"}],"explanation":["약속이에요.","74쪽이에요.","진심을 보여요."],"asset":{"type":"passage","lines":["잘못했을 때는 상대에게 꼭 사과해야 해요.","마음속으로만 생각하면 상대는 알 수 없어요.","왜 미안한지 말하고, 다시는 그러지 않겠다고 약속해요.","받아 줄지는 상처받은 상대가 정해요.","그래서 「내 사과를 받아 줄래?」 하고 정중하게 물어봐요.","상대 잘못을 따지거나 「하지만…….」 하고 변명하지 않아요.","깨끗하게 잘못을 인정하고 진심으로 사과해요."],"title":"『국어』 74~75쪽 「진심으로 사과하는 법을 알아 둬」(박현숙) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L03_challenge#8','kor',2,2,'u3','L03','g2_2_kor_u3_L03_challenge','lesson_challenge','K2-2-u3-C4',4,'sa','auto','중심 내용을 찾을 때 글쓴이가 그렇게 말한 (    )을 찾아요. 빈칸에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u3-C4","difficulty":4,"kind":"sa","stem":"중심 내용을 찾을 때 글쓴이가 그렇게 말한 (    )을 찾아요. 빈칸에 알맞은 두 글자를 쓰세요.","answer":["까닭"],"explanation":["까닭이에요.","77쪽 4번이에요.","왜 그렇게 말했는지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L03_challenge#9','kor',2,2,'u3','L03','g2_2_kor_u3_L03_challenge','lesson_challenge','K2-2-u3-C3',4,'essay','teacher','친구의 필통을 실수로 떨어뜨렸어요. 이 글에서 배운 대로 사과하는 말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u3-C3","difficulty":4,"kind":"essay","stem":"친구의 필통을 실수로 떨어뜨렸어요. 이 글에서 배운 대로 사과하는 말을 쓰세요.","answer_guide":{"answer":"예: 미안해. 내가 급하게 지나가다가 네 필통을 떨어뜨렸어. 다음부터 조심할게. 내 사과를 받아 줄래?","scoring_points":["미안한 까닭을 말했어요","다시 그러지 않겠다는 약속이 있어요","변명하지 않았어요"]},"explanation":["까닭을 말해요.","약속하고 정중하게 물어요.","74~75쪽이에요."],"asset":{"type":"passage","lines":["잘못했을 때는 상대에게 꼭 사과해야 해요.","마음속으로만 생각하면 상대는 알 수 없어요.","왜 미안한지 말하고, 다시는 그러지 않겠다고 약속해요.","받아 줄지는 상처받은 상대가 정해요.","그래서 「내 사과를 받아 줄래?」 하고 정중하게 물어봐요.","상대 잘못을 따지거나 「하지만…….」 하고 변명하지 않아요.","깨끗하게 잘못을 인정하고 진심으로 사과해요."],"title":"『국어』 74~75쪽 「진심으로 사과하는 법을 알아 둬」(박현숙) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L03_challenge#10','kor',2,2,'u3','L03','g2_2_kor_u3_L03_challenge','lesson_challenge','K2-2-u3-C4',4,'essay','teacher','「진심으로 사과하는 법을 알아 둬」의 중심 내용을 한 문장으로 쓰고, 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u3-C4","difficulty":4,"kind":"essay","stem":"「진심으로 사과하는 법을 알아 둬」의 중심 내용을 한 문장으로 쓰고, 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 사과할 때는 까닭을 말하고 변명 없이 진심으로 해야 한다. / 까닭: 제목도 사과하는 법이고, 글 내내 어떻게 사과해야 하는지 말하기 때문이에요.","scoring_points":["중심 내용이 있어요","그렇게 생각한 까닭이 있어요"]},"explanation":["하고 싶은 말을 모아요.","까닭을 함께 써요.","77쪽 (4)예요."],"asset":{"type":"passage","lines":["잘못했을 때는 상대에게 꼭 사과해야 해요.","마음속으로만 생각하면 상대는 알 수 없어요.","왜 미안한지 말하고, 다시는 그러지 않겠다고 약속해요.","받아 줄지는 상처받은 상대가 정해요.","그래서 「내 사과를 받아 줄래?」 하고 정중하게 물어봐요.","상대 잘못을 따지거나 「하지만…….」 하고 변명하지 않아요.","깨끗하게 잘못을 인정하고 진심으로 사과해요."],"title":"『국어』 74~75쪽 「진심으로 사과하는 법을 알아 둬」(박현숙) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L05_basic#1','kor',2,2,'u3','L05','g2_2_kor_u3_L05_basic','lesson_basic','K2-2-u3-C5',1,'mc','auto','『국어』 81쪽 (1) — 빗자루는 무엇을 할 때 쓰는 물건인가요?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":1,"concept":"K2-2-u3-C5","difficulty":1,"kind":"mc","stem":"『국어』 81쪽 (1) — 빗자루는 무엇을 할 때 쓰는 물건인가요?","options":[{"t":"먼지나 쓰레기를 쓸어 모을 때","correct":true},{"t":"밥을 지을 때","mis":"K2-2-u3-X04"},{"t":"옷을 꿰맬 때","mis":"K2-2-u3-X04"}],"explanation":["청소 도구예요.","81쪽 예시 답안이에요.","첫 덩어리에 있어요."],"asset":{"type":"passage","lines":["빗자루는 먼지나 쓰레기를 쓸어 모으는 청소 도구예요.","수수·갈대·댑싸리·대나무 같은 것을 묶어 만들어요.","먼저 줄기를 소금물에 삶아 그늘에 말리고, 나락·꽃가루를 긁어내요.","줄기를 가지런히 묶은 뒤 끝을 가지런히 잘라요.","재료나 생김새에 따라 이름이 달라요.","싸리비(싸리) · 장목비(수수) · 갈목비(갈대 이삭)","대장 비(대나무 손잡이) · 솔비(솔가지) · 꽃비(수 놓은 방비)","옛날에는 빗자루로 인형 놀이도 했어요."],"title":"『국어』 78~80쪽 「빗자루」(윤혜신) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L05_basic#2','kor',2,2,'u3','L05','g2_2_kor_u3_L05_basic','lesson_basic','K2-2-u3-C5',1,'mc','auto','『국어』 81쪽 (2) — 빗자루를 만드는 재료가 아닌 것은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":2,"concept":"K2-2-u3-C5","difficulty":1,"kind":"mc","stem":"『국어』 81쪽 (2) — 빗자루를 만드는 재료가 아닌 것은?","options":[{"t":"벽돌","correct":true},{"t":"수수","mis":"K2-2-u3-X04"},{"t":"갈대","mis":"K2-2-u3-X04"}],"explanation":["수수·갈대·싸리·대나무 등이에요.","벽돌은 없어요.","81쪽이에요."],"asset":{"type":"passage","lines":["빗자루는 먼지나 쓰레기를 쓸어 모으는 청소 도구예요.","수수·갈대·댑싸리·대나무 같은 것을 묶어 만들어요.","먼저 줄기를 소금물에 삶아 그늘에 말리고, 나락·꽃가루를 긁어내요.","줄기를 가지런히 묶은 뒤 끝을 가지런히 잘라요.","재료나 생김새에 따라 이름이 달라요.","싸리비(싸리) · 장목비(수수) · 갈목비(갈대 이삭)","대장 비(대나무 손잡이) · 솔비(솔가지) · 꽃비(수 놓은 방비)","옛날에는 빗자루로 인형 놀이도 했어요."],"title":"『국어』 78~80쪽 「빗자루」(윤혜신) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L05_basic#3','kor',2,2,'u3','L05','g2_2_kor_u3_L05_basic','lesson_basic','K2-2-u3-C2',1,'mc','auto','『국어』 78쪽 — 제목 「빗자루」와 사진을 보고 짐작할 수 있는 것은?',ARRAY['K2-2-u3-X03']::text[],false,'{"seq":3,"concept":"K2-2-u3-C2","difficulty":1,"kind":"mc","stem":"『국어』 78쪽 — 제목 「빗자루」와 사진을 보고 짐작할 수 있는 것은?","options":[{"t":"빗자루에 대해 설명하는 글이에요","correct":true},{"t":"곡식을 거두는 방법이에요","mis":"K2-2-u3-X03"},{"t":"그림 그리는 방법이에요","mis":"K2-2-u3-X03"}],"explanation":["제목이 빗자루예요.","82쪽 (1) 예시 답안이에요.","사진도 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
