INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L05_challenge#5','kor',2,2,'u3','L05','g2_2_kor_u3_L05_challenge','lesson_challenge','K2-2-u3-C5',3,'match','auto','『국어』 83쪽 (5) — 칸과 중심 내용을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K2-2-u3-C5","difficulty":3,"kind":"match","stem":"『국어』 83쪽 (5) — 칸과 중심 내용을 이어 보세요.","pairs":[{"l":"쓰임새","r":"먼지나 쓰레기를 쓸어 모으는 청소 도구"},{"l":"여러 가지 빗자루 이름","r":"재료나 생김새에 따라 이름이 달라진다"},{"l":"빗자루로 하는 놀이","r":"인형 놀이"}],"mis":"K2-2-u3-X07","explanation":["칸마다 중심 내용이에요.","83쪽 예시 답안이에요.","한눈에 간추려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L05_challenge#6','kor',2,2,'u3','L05','g2_2_kor_u3_L05_challenge','lesson_challenge','K2-2-u3-C5',3,'mc','auto','「빗자루」를 알맞게 간추린 것은?',ARRAY['K2-2-u3-X07']::text[],false,'{"seq":6,"concept":"K2-2-u3-C5","difficulty":3,"kind":"mc","stem":"「빗자루」를 알맞게 간추린 것은?","options":[{"t":"빗자루는 먼지를 쓸어 모으는 청소 도구로, 줄기를 삶고 말려 묶어 만들며, 재료나 생김새에 따라 이름이 달라요","correct":true},{"t":"빗자루 끝은 가지런히 잘라요","mis":"K2-2-u3-X07"},{"t":"서양에는 빗자루를 타고 나는 마법사가 있어요","mis":"K2-2-u3-X07"}],"explanation":["중요한 내용을 이었어요.","82~83쪽이에요.","짧게 모아요."],"asset":{"type":"passage","lines":["빗자루는 먼지나 쓰레기를 쓸어 모으는 청소 도구예요.","수수·갈대·댑싸리·대나무 같은 것을 묶어 만들어요.","먼저 줄기를 소금물에 삶아 그늘에 말리고, 나락·꽃가루를 긁어내요.","줄기를 가지런히 묶은 뒤 끝을 가지런히 잘라요.","재료나 생김새에 따라 이름이 달라요.","싸리비(싸리) · 장목비(수수) · 갈목비(갈대 이삭)","대장 비(대나무 손잡이) · 솔비(솔가지) · 꽃비(수 놓은 방비)","옛날에는 빗자루로 인형 놀이도 했어요."],"title":"『국어』 78~80쪽 「빗자루」(윤혜신) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L05_challenge#7','kor',2,2,'u3','L05','g2_2_kor_u3_L05_challenge','lesson_challenge','K2-2-u3-C5',3,'ox','auto','글을 간추릴 때에는 글의 모든 문장을 그대로 옮겨 써요.',ARRAY['K2-2-u3-X07']::text[],false,'{"seq":7,"concept":"K2-2-u3-C5","difficulty":3,"kind":"ox","stem":"글을 간추릴 때에는 글의 모든 문장을 그대로 옮겨 써요.","answer":"X","reason_options":[{"t":"중요한 내용만 골라 이어야 짧게 간추릴 수 있으니까","correct":true},{"t":"모든 문장이 똑같이 중요하니까","mis":"K2-2-u3-X07"}],"mis":"K2-2-u3-X07","explanation":["중요한 것만 골라요.","지도서 144쪽이에요.","이어서 짧게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L05_challenge#8','kor',2,2,'u3','L05','g2_2_kor_u3_L05_challenge','lesson_challenge','K2-2-u3-C6',4,'sa','auto','「묶어」와 뜻이 반대인 낱말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u3-C6","difficulty":4,"kind":"sa","stem":"「묶어」와 뜻이 반대인 낱말을 쓰세요.","answer":["풀어"],"explanation":["풀어예요.","81쪽이에요.","묶은 것을 푸는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L05_challenge#9','kor',2,2,'u3','L05','g2_2_kor_u3_L05_challenge','lesson_challenge','K2-2-u3-C5',4,'essay','teacher','빗자루를 만드는 방법을 차례대로 간단히 쓰세요. 「먼저」, 「그다음에」, 「마지막으로」를 넣으세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u3-C5","difficulty":4,"kind":"essay","stem":"빗자루를 만드는 방법을 차례대로 간단히 쓰세요. 「먼저」, 「그다음에」, 「마지막으로」를 넣으세요.","answer_guide":{"answer":"예: 먼저 줄기를 소금물에 삶아요. 그다음에 그늘에 말려 깨끗이 긁어내고 가지런히 묶어요. 마지막으로 자루 끝을 가지런히 잘라요.","scoring_points":["차례가 맞아요","차례를 알려 주는 말을 넣었어요"]},"explanation":["차례대로 써요.","차례 말을 넣어요.","79쪽이에요."],"asset":{"type":"passage","lines":["빗자루는 먼지나 쓰레기를 쓸어 모으는 청소 도구예요.","수수·갈대·댑싸리·대나무 같은 것을 묶어 만들어요.","먼저 줄기를 소금물에 삶아 그늘에 말리고, 나락·꽃가루를 긁어내요.","줄기를 가지런히 묶은 뒤 끝을 가지런히 잘라요.","재료나 생김새에 따라 이름이 달라요.","싸리비(싸리) · 장목비(수수) · 갈목비(갈대 이삭)","대장 비(대나무 손잡이) · 솔비(솔가지) · 꽃비(수 놓은 방비)","옛날에는 빗자루로 인형 놀이도 했어요."],"title":"『국어』 78~80쪽 「빗자루」(윤혜신) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L05_challenge#10','kor',2,2,'u3','L05','g2_2_kor_u3_L05_challenge','lesson_challenge','K2-2-u3-C5',4,'essay','teacher','「빗자루」를 읽고 새롭게 안 점이나 더 궁금한 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u3-C5","difficulty":4,"kind":"essay","stem":"「빗자루」를 읽고 새롭게 안 점이나 더 궁금한 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 빗자루를 만들 때 줄기를 소금물에 삶는다는 것을 새롭게 알았어요. / 오늘날 빗자루는 무엇으로 만드는지 궁금해요.","scoring_points":["새롭게 안 점이나 궁금한 점이 있어요","글 내용과 이어져요"]},"explanation":["읽은 내용을 떠올려요.","더 알고 싶은 것도 좋아요.","지도서 143쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L07_basic#1','kor',2,2,'u3','L07','g2_2_kor_u3_L07_basic','lesson_basic','K2-2-u3-C7',1,'mc','auto','『국어』 86쪽 2번 (1) — 「여러 가지 옷차림」은 무엇을 설명하나요?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":1,"concept":"K2-2-u3-C7","difficulty":1,"kind":"mc","stem":"『국어』 86쪽 2번 (1) — 「여러 가지 옷차림」은 무엇을 설명하나요?","options":[{"t":"옷차림","correct":true},{"t":"수영하는 방법","mis":"K2-2-u3-X04"},{"t":"요리하는 방법","mis":"K2-2-u3-X04"}],"explanation":["옷차림이에요.","86쪽 예시 답안이에요.","제목에도 있어요."],"asset":{"type":"passage","lines":["우리는 날마다 여러 가지 옷을 볼 수 있습니다.","친구들이 입는 옷에는 치마도 있고 바지도 있습니다.","또 친구들이 입는 옷의 색이나 무늬도 다양합니다.","어떤 장소인지에 따라서 볼 수 있는 옷이 달라집니다.","수영장에서는 수영복을, 체육관이나 운동장에서는","활동하기 편한 운동복을 많이 볼 수 있습니다.","결혼식장에서 볼 수 있는 특별한 옷은 웨딩드레스입니다."],"title":"『국어』 84쪽 「여러 가지 옷차림」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
