INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L07_challenge#2','kor',2,2,'u3','L07','g2_2_kor_u3_L07_challenge','lesson_challenge','K2-2-u3-C7',2,'mc','auto','요리하는 사람이 요리용 모자를 쓰고 앞치마를 두르는 까닭은?',ARRAY['K2-2-u3-X04','K2-2-u3-X11']::text[],false,'{"seq":2,"concept":"K2-2-u3-C7","difficulty":2,"kind":"mc","stem":"요리하는 사람이 요리용 모자를 쓰고 앞치마를 두르는 까닭은?","options":[{"t":"음식을 청결하게 만들려고","correct":true},{"t":"불로부터 몸을 보호하려고","mis":"K2-2-u3-X04"},{"t":"멋을 내려고","mis":"K2-2-u3-X11"}],"explanation":["청결하게요.","85쪽이에요.","하는 일에 따라요."],"asset":{"type":"passage","lines":["하는 일에 따라서도 옷차림이 달라집니다.","소방관은 뜨거운 불로부터 몸을 보호하려고","헬멧과 장갑, 열을 막을 수 있는 특별한 옷을 입습니다.","요리하는 사람은 음식을 청결하게 만들려고","요리용 모자를 쓰거나 앞치마를 두릅니다."],"title":"『국어』 85쪽 「여러 가지 옷차림」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
