INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L07_challenge#4','kor',2,2,'u3','L07','g2_2_kor_u3_L07_challenge','lesson_challenge','K2-2-u3-C7',3,'mc','auto','『국어』 86쪽 (3) — 「모자나 신발도 옷이라고 할 수 있을까?」처럼 궁금한 점을 말하면 좋은 까닭은?',ARRAY['K2-2-u3-X04','K2-2-u3-X11']::text[],false,'{"seq":4,"concept":"K2-2-u3-C7","difficulty":3,"kind":"mc","stem":"『국어』 86쪽 (3) — 「모자나 신발도 옷이라고 할 수 있을까?」처럼 궁금한 점을 말하면 좋은 까닭은?","options":[{"t":"더 알고 싶은 내용을 찾아 새로운 글감이 생겨요","correct":true},{"t":"글을 다시 읽지 않아도 돼요","mis":"K2-2-u3-X04"},{"t":"친구를 놀릴 수 있어요","mis":"K2-2-u3-X11"}],"explanation":["글감이 생겨요.","86쪽이에요.","더 알아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L07_challenge#5','kor',2,2,'u3','L07','g2_2_kor_u3_L07_challenge','lesson_challenge','K2-2-u3-C7',3,'mc','auto','「여러 가지 옷차림」에 「날씨에 따라」 덩어리를 더 쓴다면 들어갈 내용은?',ARRAY['K2-2-u3-X02']::text[],false,'{"seq":5,"concept":"K2-2-u3-C7","difficulty":3,"kind":"mc","stem":"「여러 가지 옷차림」에 「날씨에 따라」 덩어리를 더 쓴다면 들어갈 내용은?","options":[{"t":"추울 때는 두껍고 소매가 긴 옷을 입어요","correct":true},{"t":"나는 겨울이 좋아요","mis":"K2-2-u3-X02"},{"t":"비 오는 날 우산을 잃어버렸어요","mis":"K2-2-u3-X02"}],"explanation":["날씨에 따른 옷이에요.","87쪽 4번이에요.","특징만 써요."],"asset":{"type":"passage","lines":["날씨에 따라서 입는 옷이 달라지기도 합니다.","날씨가 더울 때에는 두께가 얇고, 소매가 짧은 옷을 입습니다.","날씨가 추울 때에는 두께가 두껍고, 소매가 긴 옷을 입습니다.","비가 오는 날에는 비옷을 입고 장화를 신기도 합니다."],"title":"『국어』 87쪽 4번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L07_challenge#6','kor',2,2,'u3','L07','g2_2_kor_u3_L07_challenge','lesson_challenge','K2-2-u3-C7',3,'ox','auto','옷차림을 설명하는 글에는 어떤 옷이 더 예쁜지 내 생각을 써야 해요.',ARRAY['K2-2-u3-X11']::text[],false,'{"seq":6,"concept":"K2-2-u3-C7","difficulty":3,"kind":"ox","stem":"옷차림을 설명하는 글에는 어떤 옷이 더 예쁜지 내 생각을 써야 해요.","answer":"X","reason_options":[{"t":"설명하는 글은 누구나 알 수 있는 사실과 특징을 쓰니까","correct":true},{"t":"내 생각이 가장 중요하니까","mis":"K2-2-u3-X11"}],"mis":"K2-2-u3-X11","explanation":["사실을 써요.","지도서 146쪽이에요.","좋고 나쁨은 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L07_challenge#7','kor',2,2,'u3','L07','g2_2_kor_u3_L07_challenge','lesson_challenge','K2-2-u3-C8',3,'mc','auto','「없잖아」, 「않는」, 「얇고」의 공통점은?',ARRAY['K2-2-u3-X13']::text[],false,'{"seq":7,"concept":"K2-2-u3-C8","difficulty":3,"kind":"mc","stem":"「없잖아」, 「않는」, 「얇고」의 공통점은?","options":[{"t":"받침이 두 글자로 된 겹받침이 있어요","correct":true},{"t":"모두 받침이 없어요","mis":"K2-2-u3-X13"},{"t":"모두 소리 나는 대로 써요","mis":"K2-2-u3-X13"}],"explanation":["겹받침이에요.","99쪽 글씨 쓰기예요.","소리와 쓰는 법이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L07_challenge#8','kor',2,2,'u3','L07','g2_2_kor_u3_L07_challenge','lesson_challenge','K2-2-u3-C7',4,'sa','auto','설명하는 글을 쓰려면 먼저 설명하려는 (    )을 정해요. 빈칸에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u3-C7","difficulty":4,"kind":"sa","stem":"설명하는 글을 쓰려면 먼저 설명하려는 (    )을 정해요. 빈칸에 알맞은 두 글자를 쓰세요.","answer":["대상"],"explanation":["대상이에요.","87쪽 5번이에요.","무엇을 설명할지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L07_challenge#9','kor',2,2,'u3','L07','g2_2_kor_u3_L07_challenge','lesson_challenge','K2-2-u3-C7',4,'essay','teacher','「날씨에 따라 옷차림이 달라집니다.」 뒤에 이어질 문장을 두 개 쓰세요. 겹받침 낱말에 주의하세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u3-C7","difficulty":4,"kind":"essay","stem":"「날씨에 따라 옷차림이 달라집니다.」 뒤에 이어질 문장을 두 개 쓰세요. 겹받침 낱말에 주의하세요.","answer_guide":{"answer":"예: 더울 때에는 얇고 소매가 짧은 옷을 입습니다. 비가 오는 날에는 비옷을 입고 장화를 신습니다.","scoring_points":["날씨에 따른 옷이에요","문장이 두 개예요","겹받침을 바르게 썼어요"]},"explanation":["날씨에 따른 옷을 써요.","겹받침을 살펴요.","87쪽 4번이에요."],"asset":{"type":"passage","lines":["날씨에 따라서 입는 옷이 달라지기도 합니다.","날씨가 더울 때에는 두께가 얇고, 소매가 짧은 옷을 입습니다.","날씨가 추울 때에는 두께가 두껍고, 소매가 긴 옷을 입습니다.","비가 오는 날에는 비옷을 입고 장화를 신기도 합니다."],"title":"『국어』 87쪽 4번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L07_challenge#10','kor',2,2,'u3','L07','g2_2_kor_u3_L07_challenge','lesson_challenge','K2-2-u3-C7',4,'essay','teacher','우리 학교에서 볼 수 있는 옷차림(체육 시간·급식실 등) 하나를 골라, 장소나 하는 일에 따라 어떤 옷을 입는지 설명하는 문장을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u3-C7","difficulty":4,"kind":"essay","stem":"우리 학교에서 볼 수 있는 옷차림(체육 시간·급식실 등) 하나를 골라, 장소나 하는 일에 따라 어떤 옷을 입는지 설명하는 문장을 쓰세요.","answer_guide":{"answer":"예: 급식실에서 일하시는 분들은 음식을 청결하게 만들려고 위생 모자와 앞치마를 쓰십니다.","scoring_points":["장소나 하는 일이 있어요","어떤 옷인지 있어요","좋고 나쁨이 아니라 사실을 썼어요"]},"explanation":["장소·하는 일을 정해요.","사실을 써요.","85쪽처럼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L09_basic#1','kor',2,2,'u3','L09','g2_2_kor_u3_L09_basic','lesson_basic','K2-2-u3-C9',1,'mc','auto','지도서 151쪽 세 고개 놀이 — 설명을 듣고 무엇인지 알아맞혀 보세요.',ARRAY['K2-2-u3-X01']::text[],false,'{"seq":1,"concept":"K2-2-u3-C9","difficulty":1,"kind":"mc","stem":"지도서 151쪽 세 고개 놀이 — 설명을 듣고 무엇인지 알아맞혀 보세요.","options":[{"t":"시계","correct":true},{"t":"자전거","mis":"K2-2-u3-X01"},{"t":"농구공","mis":"K2-2-u3-X01"}],"explanation":["시계예요.","세 가지 특징이 모였어요.","지도서 151쪽이에요."],"asset":{"type":"passage","lines":["① 동그라미를 그리며 움직인다.","② 얼굴에 숫자가 있다.","③ 시간을 알려 준다."],"title":"지도서 151쪽 세 고개 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
