INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L09_basic#4','kor',2,2,'u3','L09','g2_2_kor_u3_L09_basic','lesson_basic','K2-2-u3-C9',1,'mc','auto','『국어』 91쪽 점검하기 — 내 글을 점검하는 질문으로 알맞은 것은?',ARRAY['K2-2-u3-X12','K2-2-u3-X01']::text[],false,'{"seq":4,"concept":"K2-2-u3-C9","difficulty":1,"kind":"mc","stem":"『국어』 91쪽 점검하기 — 내 글을 점검하는 질문으로 알맞은 것은?","options":[{"t":"설명하려는 대상의 특징이 잘 드러나게 썼나요?","correct":true},{"t":"글씨를 크게만 썼나요?","mis":"K2-2-u3-X12"},{"t":"글이 아주 긴가요?","mis":"K2-2-u3-X01"}],"explanation":["특징이 드러났는지 봐요.","91쪽이에요.","자세히·궁금한 내용도요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L09_basic#5','kor',2,2,'u3','L09','g2_2_kor_u3_L09_basic','lesson_basic','K2-2-u3-C9',2,'mc','auto','「선생님은 고추장으로 맛을 낸 떡볶이를 좋아합니다.」에서 알 수 있는 특징은?',ARRAY['K2-2-u3-X01','K2-2-u3-X02']::text[],false,'{"seq":5,"concept":"K2-2-u3-C9","difficulty":2,"kind":"mc","stem":"「선생님은 고추장으로 맛을 낸 떡볶이를 좋아합니다.」에서 알 수 있는 특징은?","options":[{"t":"맛과 재료","correct":true},{"t":"크기와 무게","mis":"K2-2-u3-X01"},{"t":"사는 곳","mis":"K2-2-u3-X02"}],"explanation":["맛과 재료예요.","지도서 152쪽이에요.","「고추장으로 맛을 낸」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L09_basic#6','kor',2,2,'u3','L09','g2_2_kor_u3_L09_basic','lesson_basic','K2-2-u3-C9',2,'mc','auto','『국어』 89쪽 — 친구가 「어떤 먹이를 먹는지 궁금해.」라고 했어요. 어떻게 할까요?',ARRAY['K2-2-u3-X12']::text[],false,'{"seq":6,"concept":"K2-2-u3-C9","difficulty":2,"kind":"mc","stem":"『국어』 89쪽 — 친구가 「어떤 먹이를 먹는지 궁금해.」라고 했어요. 어떻게 할까요?","options":[{"t":"먹이 이야기를 글에 넣어 써요","correct":true},{"t":"친구 질문은 신경 쓰지 않아요","mis":"K2-2-u3-X12"},{"t":"다른 물건으로 바꾸어요","mis":"K2-2-u3-X12"}],"explanation":["궁금한 내용을 넣어요.","89쪽이에요.","읽는 사람을 생각해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"내가 기르는 물고기의 어떤 점을 알고 싶어?"},{"who":"친구 2","text":"얼마나 큰지, 무슨 색인지 알려 주면 좋겠어."},{"who":"친구 3","text":"어떤 먹이를 먹는지 궁금해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L09_basic#7','kor',2,2,'u3','L09','g2_2_kor_u3_L09_basic','lesson_basic','K2-2-u3-C9',2,'mc','auto','「떡볶이 — 매콤」을 설명하는 문장으로 알맞게 나타낸 것은?',ARRAY['K2-2-u3-X15']::text[],false,'{"seq":7,"concept":"K2-2-u3-C9","difficulty":2,"kind":"mc","stem":"「떡볶이 — 매콤」을 설명하는 문장으로 알맞게 나타낸 것은?","options":[{"t":"떡볶이의 맛은 매콤합니다.","correct":true},{"t":"떡볶이 매콤.","mis":"K2-2-u3-X15"},{"t":"매콤하다 떡볶이는?","mis":"K2-2-u3-X15"}],"explanation":["대상과 특징을 한 문장에요.","지도서 153쪽이에요.","「○○의 △△은 □□합니다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L09_basic#8','kor',2,2,'u3','L09','g2_2_kor_u3_L09_basic','lesson_basic','K2-2-u3-C9',2,'mc','auto','『국어』 91쪽 (2) — 친구 글 「동그랗고 빨간색입니다. 겉은 매끈하고 속은 아삭합니다. 달콤한 맛이 납니다. 나무에 열립니다.」 — 무엇일까요?',ARRAY['K2-2-u3-X01']::text[],false,'{"seq":8,"concept":"K2-2-u3-C9","difficulty":2,"kind":"mc","stem":"『국어』 91쪽 (2) — 친구 글 「동그랗고 빨간색입니다. 겉은 매끈하고 속은 아삭합니다. 달콤한 맛이 납니다. 나무에 열립니다.」 — 무엇일까요?","options":[{"t":"사과","correct":true},{"t":"토마토","mis":"K2-2-u3-X01"},{"t":"풍선","mis":"K2-2-u3-X01"}],"explanation":["사과예요.","특징이 여러 가지예요.","91쪽 알아맞히기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L09_basic#9','kor',2,2,'u3','L09','g2_2_kor_u3_L09_basic','lesson_basic','K2-2-u3-C9',2,'ox','auto','친구가 내 글을 읽고 무엇인지 알아맞히지 못했다면 특징을 더 써서 고쳐 써요.',ARRAY['K2-2-u3-X12']::text[],false,'{"seq":9,"concept":"K2-2-u3-C9","difficulty":2,"kind":"ox","stem":"친구가 내 글을 읽고 무엇인지 알아맞히지 못했다면 특징을 더 써서 고쳐 써요.","answer":"O","reason_options":[{"t":"읽는 사람이 알 수 있게 특징이 더 필요하니까","correct":true},{"t":"친구가 잘 안 읽은 탓이니까","mis":"K2-2-u3-X12"}],"mis":"K2-2-u3-X12","explanation":["특징을 보태요.","91쪽 도움말이에요.","고쳐 쓰기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
