INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L09_challenge#7','kor',2,2,'u3','L09','g2_2_kor_u3_L09_challenge','lesson_challenge','K2-2-u3-C9',3,'ox','auto','친구들이 많이 물어본 내용은 설명하는 글에 넣지 않아요.',ARRAY['K2-2-u3-X12']::text[],false,'{"seq":7,"concept":"K2-2-u3-C9","difficulty":3,"kind":"ox","stem":"친구들이 많이 물어본 내용은 설명하는 글에 넣지 않아요.","answer":"X","reason_options":[{"t":"많이 묻는 내용은 읽는 사람이 궁금해하는 내용이니까","correct":true},{"t":"질문은 대화할 때만 하는 거니까","mis":"K2-2-u3-X12"}],"mis":"K2-2-u3-X12","explanation":["궁금한 내용은 넣어요.","지도서 153쪽이에요.","읽는 사람을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L09_challenge#8','kor',2,2,'u3','L09','g2_2_kor_u3_L09_challenge','lesson_challenge','K2-2-u3-C9',4,'sa','auto','『국어』 91쪽 — 고쳐 쓴 글을 이용해 하는 놀이는 무엇인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u3-C9","difficulty":4,"kind":"sa","stem":"『국어』 91쪽 — 고쳐 쓴 글을 이용해 하는 놀이는 무엇인가요? 네 글자로 쓰세요.","answer":["수수께끼"],"explanation":["수수께끼예요.","91쪽 더 나아가기예요.","붙임 7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L09_challenge#9','kor',2,2,'u3','L09','g2_2_kor_u3_L09_challenge','lesson_challenge','K2-2-u3-C9',4,'essay','teacher','내가 좋아하는 물건 하나를 골라, 대상과 특징이 드러나게 세 문장 이상으로 설명하는 글을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u3-C9","difficulty":4,"kind":"essay","stem":"내가 좋아하는 물건 하나를 골라, 대상과 특징이 드러나게 세 문장 이상으로 설명하는 글을 쓰세요.","answer_guide":{"answer":"예: 제가 좋아하는 것은 자전거입니다. 자전거는 바퀴가 두 개입니다. 발로 페달을 밟아 앞으로 갑니다. 탈 때에는 헬멧을 써야 합니다.","scoring_points":["대상이 드러나요","대상에 알맞은 특징이 있어요","세 문장 이상이에요"]},"explanation":["대상을 먼저 써요.","특징을 여러 가지요.","90쪽 글쓰기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L09_challenge#10','kor',2,2,'u3','L09','g2_2_kor_u3_L09_challenge','lesson_challenge','K2-2-u3-C9',4,'essay','teacher','친구가 쓴 「제가 좋아하는 것은 공입니다. 둥급니다.」를 읽고 무엇을 더 쓰면 좋을지 친구에게 조언하는 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u3-C9","difficulty":4,"kind":"essay","stem":"친구가 쓴 「제가 좋아하는 것은 공입니다. 둥급니다.」를 읽고 무엇을 더 쓰면 좋을지 친구에게 조언하는 말을 쓰세요.","answer_guide":{"answer":"예: 어떤 공인지 알기 어려워. 크기나 색깔, 어떤 놀이를 할 때 쓰는지 더 쓰면 좋겠어.","scoring_points":["더 쓸 특징을 말했어요","친구 기분을 생각한 말이에요"]},"explanation":["빠진 특징을 찾아요.","부드럽게 말해요.","91쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
