INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L11_basic#6','kor',2,2,'u3','L11','g2_2_kor_u3_L11_basic','lesson_basic','K2-2-u3-C10',2,'mc','auto','놀이 방법을 알기 쉽게 쓰려면 어떻게 할까요?',ARRAY['K2-2-u3-X10','K2-2-u3-X14']::text[],false,'{"seq":6,"concept":"K2-2-u3-C10","difficulty":2,"kind":"mc","stem":"놀이 방법을 알기 쉽게 쓰려면 어떻게 할까요?","options":[{"t":"숫자로 차례를 붙이고 그림에 짧은 설명을 더해요","correct":true},{"t":"쉬지 않고 한 줄로 길게 써요","mis":"K2-2-u3-X10"},{"t":"그림만 그리고 글은 쓰지 않아요","mis":"K2-2-u3-X14"}],"explanation":["차례를 나타내요.","지도서 155쪽이에요.","표나 숫자도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L11_basic#7','kor',2,2,'u3','L11','g2_2_kor_u3_L11_basic','lesson_basic','K2-2-u3-C10',2,'mc','auto','놀이 이름보다 놀이 방법을 자세히 써야 하는 까닭은?',ARRAY['K2-2-u3-X14']::text[],false,'{"seq":7,"concept":"K2-2-u3-C10","difficulty":2,"kind":"mc","stem":"놀이 이름보다 놀이 방법을 자세히 써야 하는 까닭은?","options":[{"t":"같은 놀이도 이름과 규칙이 달라서, 방법을 써야 친구가 따라 할 수 있어요","correct":true},{"t":"놀이 이름은 쓰면 안 되기 때문이에요","mis":"K2-2-u3-X14"},{"t":"글을 길게 쓰기 위해서예요","mis":"K2-2-u3-X14"}],"explanation":["방법을 써야 해요.","지도서 154쪽이에요.","따라 할 수 있게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L11_basic#8','kor',2,2,'u3','L11','g2_2_kor_u3_L11_basic','lesson_basic','K2-2-u3-C10',2,'mc','auto','지도서 예시 1 — 「나도!」 점수는 어떻게 매기나요?',ARRAY['K2-2-u3-X14']::text[],false,'{"seq":8,"concept":"K2-2-u3-C10","difficulty":2,"kind":"mc","stem":"지도서 예시 1 — 「나도!」 점수는 어떻게 매기나요?","options":[{"t":"낱말을 말한 사람과 「나도!」 한 사람 수를 더해요","correct":true},{"t":"글씨를 예쁘게 쓴 사람이 받아요","mis":"K2-2-u3-X14"},{"t":"가장 긴 낱말이 받아요","mis":"K2-2-u3-X14"}],"explanation":["사람 수를 더해요.","아무도 없으면 0점이에요.","지도서 156쪽이에요."],"asset":{"type":"passage","lines":["그림책 표지를 보고 친구들도 생각했을 법한 낱말 세 개를 써요.","표지에 나와 있는 낱말은 쓸 수 없어요.","돌아가며 한 개씩 읽고, 같은 낱말을 쓴 친구는 「나도!」 해요.","말한 사람과 「나도!」 한 사람 수를 더해 점수를 써요.","아무도 「나도!」 하지 않으면 0점이에요."],"title":"지도서 156쪽 예시 1 — 책 표지를 낱말로 설명하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L11_basic#9','kor',2,2,'u3','L11','g2_2_kor_u3_L11_basic','lesson_basic','K2-2-u3-C10',2,'mc','auto','지도서 예시 2 — 술래의 설명을 들은 친구들은 어떻게 답하나요?',ARRAY['K2-2-u3-X14']::text[],false,'{"seq":9,"concept":"K2-2-u3-C10","difficulty":2,"kind":"mc","stem":"지도서 예시 2 — 술래의 설명을 들은 친구들은 어떻게 답하나요?","options":[{"t":"말하거나 고개를 끄덕이지 않고 신호등으로만 답해요","correct":true},{"t":"정답을 크게 말해 줘요","mis":"K2-2-u3-X14"},{"t":"고개를 끄덕여 알려 줘요","mis":"K2-2-u3-X14"}],"explanation":["신호등으로만요.","지도서 157쪽이에요.","예·모름·아니요예요."],"asset":{"type":"passage","lines":["술래 등에 낱말 쪽지를 붙여요(예: 비행기).","술래는 예상한 낱말을 설명하는 문장을 말해요.","친구들은 말이나 몸짓 없이 신호등으로만 답해요.","🟢 예 · 🟡 모름 · 🔴 아니요","다섯 번 물은 뒤 답을 말해요. 틀리면 단서를 두 번 더 얻어요."],"title":"지도서 157쪽 예시 2 — 신호등 다섯 고개 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L11_basic#10','kor',2,2,'u3','L11','g2_2_kor_u3_L11_basic','lesson_basic','K2-2-u3-C10',3,'mc','auto','놀이하다가 규칙 때문에 다툼이 생겼어요. 설명하는 글을 어떻게 하면 좋을까요?',ARRAY['K2-2-u3-X14']::text[],false,'{"seq":10,"concept":"K2-2-u3-C10","difficulty":3,"kind":"mc","stem":"놀이하다가 규칙 때문에 다툼이 생겼어요. 설명하는 글을 어떻게 하면 좋을까요?","options":[{"t":"헷갈린 규칙을 더 자세히 써서 고쳐요","correct":true},{"t":"놀이를 그만둬요","mis":"K2-2-u3-X14"},{"t":"글은 그대로 둬요","mis":"K2-2-u3-X14"}],"explanation":["고쳐 써요.","92쪽 4번이에요.","막힌 곳을 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
