INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L11_challenge#2','kor',2,2,'u3','L11','g2_2_kor_u3_L11_challenge','lesson_challenge','K2-2-u3-C10',2,'mc','auto','지도서 예시 2 — 다섯 번 물은 뒤 술래가 틀리면 어떻게 하나요?',ARRAY['K2-2-u3-X14']::text[],false,'{"seq":2,"concept":"K2-2-u3-C10","difficulty":2,"kind":"mc","stem":"지도서 예시 2 — 다섯 번 물은 뒤 술래가 틀리면 어떻게 하나요?","options":[{"t":"단서를 두 번 더 얻을 수 있어요","correct":true},{"t":"바로 놀이가 끝나요","mis":"K2-2-u3-X14"},{"t":"벌칙을 받아요","mis":"K2-2-u3-X14"}],"explanation":["단서를 두 번 더요.","지도서 157쪽이에요.","두 번 연속 틀리면 바꿔요."],"asset":{"type":"passage","lines":["술래 등에 낱말 쪽지를 붙여요(예: 비행기).","술래는 예상한 낱말을 설명하는 문장을 말해요.","친구들은 말이나 몸짓 없이 신호등으로만 답해요.","🟢 예 · 🟡 모름 · 🔴 아니요","다섯 번 물은 뒤 답을 말해요. 틀리면 단서를 두 번 더 얻어요."],"title":"지도서 157쪽 예시 2 — 신호등 다섯 고개 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
