INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L11_challenge#4','kor',2,2,'u3','L11','g2_2_kor_u3_L11_challenge','lesson_challenge','K2-2-u3-C10',3,'mc','auto','술래잡기 방법을 쓸 때 빠지면 친구가 따라 하기 어려운 것은?',ARRAY['K2-2-u3-X14','K2-2-u3-X02']::text[],false,'{"seq":4,"concept":"K2-2-u3-C10","difficulty":3,"kind":"mc","stem":"술래잡기 방법을 쓸 때 빠지면 친구가 따라 하기 어려운 것은?","options":[{"t":"술래를 정하는 방법과 잡히면 어떻게 되는지","correct":true},{"t":"술래잡기를 처음 한 날","mis":"K2-2-u3-X14"},{"t":"내가 좋아하는 술래","mis":"K2-2-u3-X02"}],"explanation":["규칙이 빠지면 못 놀아요.","92쪽 보기예요.","처음 하는 친구를 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L11_challenge#5','kor',2,2,'u3','L11','g2_2_kor_u3_L11_challenge','lesson_challenge','K2-2-u3-C10',3,'mc','auto','「가위바위보로 술래를 정한다. 술래는 열을 센다. 나머지는 숨는다.」를 알기 쉽게 고친 것은?',ARRAY['K2-2-u3-X10']::text[],false,'{"seq":5,"concept":"K2-2-u3-C10","difficulty":3,"kind":"mc","stem":"「가위바위보로 술래를 정한다. 술래는 열을 센다. 나머지는 숨는다.」를 알기 쉽게 고친 것은?","options":[{"t":"① 가위바위보로 술래를 정해요. ② 술래가 열을 세요. ③ 그동안 나머지는 숨어요.","correct":true},{"t":"술래는 열을 세고 숨고 정해요.","mis":"K2-2-u3-X10"},{"t":"숨는다. 센다. 정한다.","mis":"K2-2-u3-X10"}],"explanation":["번호로 차례를 나타냈어요.","지도서 155쪽이에요.","숫자로 차례요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L11_challenge#6','kor',2,2,'u3','L11','g2_2_kor_u3_L11_challenge','lesson_challenge','K2-2-u3-C10',3,'ox','auto','놀이 방법을 설명하는 글에는 표나 그림을 쓰면 안 돼요.',ARRAY['K2-2-u3-X10']::text[],false,'{"seq":6,"concept":"K2-2-u3-C10","difficulty":3,"kind":"ox","stem":"놀이 방법을 설명하는 글에는 표나 그림을 쓰면 안 돼요.","answer":"X","reason_options":[{"t":"표나 숫자, 그림 메모를 쓰면 더 알기 쉬우니까","correct":true},{"t":"글은 줄글로만 써야 하니까","mis":"K2-2-u3-X10"}],"mis":"K2-2-u3-X10","explanation":["표·그림도 좋아요.","지도서 154쪽이에요.","알기 쉽게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L11_challenge#7','kor',2,2,'u3','L11','g2_2_kor_u3_L11_challenge','lesson_challenge','K2-2-u3-C10',3,'mc','auto','신호등 놀이에서 술래가 「주변에서 쉽게 볼 수 있어요.」 했는데 모두 🔴(아니요)를 들었어요. 무엇을 알 수 있나요?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":7,"concept":"K2-2-u3-C10","difficulty":3,"kind":"mc","stem":"신호등 놀이에서 술래가 「주변에서 쉽게 볼 수 있어요.」 했는데 모두 🔴(아니요)를 들었어요. 무엇을 알 수 있나요?","options":[{"t":"답은 주변에서 쉽게 볼 수 없는 것이에요","correct":true},{"t":"답은 주변에 많은 것이에요","mis":"K2-2-u3-X04"},{"t":"아무것도 알 수 없어요","mis":"K2-2-u3-X04"}],"explanation":["아니요라는 뜻이에요.","지도서 157쪽이에요.","다른 특징을 물어요."],"asset":{"type":"passage","lines":["술래 등에 낱말 쪽지를 붙여요(예: 비행기).","술래는 예상한 낱말을 설명하는 문장을 말해요.","친구들은 말이나 몸짓 없이 신호등으로만 답해요.","🟢 예 · 🟡 모름 · 🔴 아니요","다섯 번 물은 뒤 답을 말해요. 틀리면 단서를 두 번 더 얻어요."],"title":"지도서 157쪽 예시 2 — 신호등 다섯 고개 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L11_challenge#8','kor',2,2,'u3','L11','g2_2_kor_u3_L11_challenge','lesson_challenge','K2-2-u3-C10',4,'sa','auto','놀이에 쓰는 물건(공·구슬·종이 등)을 놀이 설명 글에서는 무엇이라고 쓰나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u3-C10","difficulty":4,"kind":"sa","stem":"놀이에 쓰는 물건(공·구슬·종이 등)을 놀이 설명 글에서는 무엇이라고 쓰나요? 세 글자로 쓰세요.","answer":["준비물"],"explanation":["준비물이에요.","92쪽 보기예요.","미리 챙겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L11_challenge#9','kor',2,2,'u3','L11','g2_2_kor_u3_L11_challenge','lesson_challenge','K2-2-u3-C10',4,'essay','teacher','친구들과 함께 하고 싶은 놀이 하나를 골라, 필요한 사람 수·준비물·놀이 방법을 차례대로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u3-C10","difficulty":4,"kind":"essay","stem":"친구들과 함께 하고 싶은 놀이 하나를 골라, 필요한 사람 수·준비물·놀이 방법을 차례대로 쓰세요.","answer_guide":{"answer":"예: 놀이 이름: 수건돌리기 / 사람 수: 다섯 명 이상 / 준비물: 수건 / 방법: ① 둥글게 앉아요. ② 술래가 돌다가 한 사람 뒤에 수건을 놓아요. ③ 알아챈 사람이 술래를 쫓아요.","scoring_points":["사람 수가 있어요","준비물이 있어요","방법이 차례대로 있어요"]},"explanation":["놀이를 하나 정해요.","차례대로 써요.","붙임 8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_L11_challenge#10','kor',2,2,'u3','L11','g2_2_kor_u3_L11_challenge','lesson_challenge','K2-2-u3-C10',4,'essay','teacher','놀이를 한 뒤 친구의 놀이 설명 글을 읽고, 도움이 된 점과 고치면 좋을 점을 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u3-C10","difficulty":4,"kind":"essay","stem":"놀이를 한 뒤 친구의 놀이 설명 글을 읽고, 도움이 된 점과 고치면 좋을 점을 하나씩 쓰세요.","answer_guide":{"answer":"예: 도움이 된 점: 번호를 붙여 차례가 잘 보였어. / 고칠 점: 잡히면 어떻게 되는지 써 주면 좋겠어.","scoring_points":["도움이 된 점이 있어요","고칠 점이 있어요"]},"explanation":["좋은 점부터요.","고칠 점은 부드럽게요.","지도서 155쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#1','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C1',1,'mc','auto','물건을 설명할 때 알맞은 것은?',ARRAY['K2-2-u3-X01','K2-2-u3-X02']::text[],false,'{"seq":1,"concept":"K2-2-u3-C1","difficulty":1,"kind":"mc","stem":"물건을 설명할 때 알맞은 것은?","options":[{"t":"알맞은 특징을 여러 가지 함께 말해요","correct":true},{"t":"모양 한 가지만 말해요","mis":"K2-2-u3-X01"},{"t":"내 기분만 말해요","mis":"K2-2-u3-X02"}],"explanation":["여러 가지요.","지도서 136쪽이에요.","그래야 알아맞혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#2','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C3',1,'mc','auto','잘못했을 때 사과해야 하는 까닭은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":2,"concept":"K2-2-u3-C3","difficulty":1,"kind":"mc","stem":"잘못했을 때 사과해야 하는 까닭은?","options":[{"t":"마음속으로만 생각하면 상대가 알 수 없어서","correct":true},{"t":"선물을 받으려고","mis":"K2-2-u3-X04"},{"t":"혼나지 않으려고","mis":"K2-2-u3-X04"}],"explanation":["말해야 전해져요.","76쪽이에요.","진심을 말로요."],"asset":{"type":"passage","lines":["잘못했을 때는 상대에게 꼭 사과해야 해요.","마음속으로만 생각하면 상대는 알 수 없어요.","왜 미안한지 말하고, 다시는 그러지 않겠다고 약속해요.","받아 줄지는 상처받은 상대가 정해요.","그래서 「내 사과를 받아 줄래?」 하고 정중하게 물어봐요.","상대 잘못을 따지거나 「하지만…….」 하고 변명하지 않아요.","깨끗하게 잘못을 인정하고 진심으로 사과해요."],"title":"『국어』 74~75쪽 「진심으로 사과하는 법을 알아 둬」(박현숙) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#3','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C5',1,'mc','auto','빗자루는 무엇을 할 때 쓰나요?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":3,"concept":"K2-2-u3-C5","difficulty":1,"kind":"mc","stem":"빗자루는 무엇을 할 때 쓰나요?","options":[{"t":"먼지나 쓰레기를 쓸어 모을 때","correct":true},{"t":"밥을 지을 때","mis":"K2-2-u3-X04"},{"t":"글씨를 쓸 때","mis":"K2-2-u3-X04"}],"explanation":["청소 도구예요.","81쪽이에요.","쓰임새예요."],"asset":{"type":"passage","lines":["빗자루는 먼지나 쓰레기를 쓸어 모으는 청소 도구예요.","수수·갈대·댑싸리·대나무 같은 것을 묶어 만들어요.","먼저 줄기를 소금물에 삶아 그늘에 말리고, 나락·꽃가루를 긁어내요.","줄기를 가지런히 묶은 뒤 끝을 가지런히 잘라요.","재료나 생김새에 따라 이름이 달라요.","싸리비(싸리) · 장목비(수수) · 갈목비(갈대 이삭)","대장 비(대나무 손잡이) · 솔비(솔가지) · 꽃비(수 놓은 방비)","옛날에는 빗자루로 인형 놀이도 했어요."],"title":"『국어』 78~80쪽 「빗자루」(윤혜신) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#4','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C7',1,'mc','auto','「여러 가지 옷차림」이 설명하는 대상은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":4,"concept":"K2-2-u3-C7","difficulty":1,"kind":"mc","stem":"「여러 가지 옷차림」이 설명하는 대상은?","options":[{"t":"옷차림","correct":true},{"t":"결혼식","mis":"K2-2-u3-X04"},{"t":"수영장","mis":"K2-2-u3-X04"}],"explanation":["옷차림이에요.","86쪽이에요.","대상을 찾아요."],"asset":{"type":"passage","lines":["우리는 날마다 여러 가지 옷을 볼 수 있습니다.","친구들이 입는 옷에는 치마도 있고 바지도 있습니다.","또 친구들이 입는 옷의 색이나 무늬도 다양합니다.","어떤 장소인지에 따라서 볼 수 있는 옷이 달라집니다.","수영장에서는 수영복을, 체육관이나 운동장에서는","활동하기 편한 운동복을 많이 볼 수 있습니다.","결혼식장에서 볼 수 있는 특별한 옷은 웨딩드레스입니다."],"title":"『국어』 84쪽 「여러 가지 옷차림」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#5','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C8',1,'mc','auto','『국어』 99쪽 — 알맞은 문장은?',ARRAY['K2-2-u3-X13']::text[],false,'{"seq":5,"concept":"K2-2-u3-C8","difficulty":1,"kind":"mc","stem":"『국어』 99쪽 — 알맞은 문장은?","options":[{"t":"수수 줄기를 소금물에 삶아요.","correct":true},{"t":"수수 줄기를 소금물에 살아요.","mis":"K2-2-u3-X13"},{"t":"수수 줄기를 소금물에 삼아요.","mis":"K2-2-u3-X13"}],"explanation":["「삶아요」예요.","99쪽이에요.","받침이 달라지면 뜻도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#6','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C5',1,'mc','auto','『국어』 95쪽 — 「글자」는 무엇을 설명하나요?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":6,"concept":"K2-2-u3-C5","difficulty":1,"kind":"mc","stem":"『국어』 95쪽 — 「글자」는 무엇을 설명하나요?","options":[{"t":"글자","correct":true},{"t":"귀","mis":"K2-2-u3-X04"},{"t":"전화","mis":"K2-2-u3-X04"}],"explanation":["글자예요.","95쪽 예시 답안이에요.","제목과 끝 문장이에요."],"asset":{"type":"passage","lines":["말은 귀로 듣고 글은 눈으로 보아요.","가까이 있는 사람들이 서로 뜻을 주고받는 데에는 말이 편해요.","그렇지만 멀리 있는 사람이나 여러 사람한테","무언가를 알리는 데에는 글이 더 편하지요.","그래서 아주 옛날부터 사람들은 글자를 썼어요."],"title":"『국어』 95쪽 「글자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
