INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#9','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C7',2,'mc','auto','『국어』 94쪽 1번 — 사물을 설명하는 글을 쓸 때 주의할 점으로 알맞은 것은?',ARRAY['K2-2-u3-X01']::text[],false,'{"seq":9,"concept":"K2-2-u3-C7","difficulty":2,"kind":"mc","stem":"『국어』 94쪽 1번 — 사물을 설명하는 글을 쓸 때 주의할 점으로 알맞은 것은?","options":[{"t":"사물의 특징이 잘 드러나게 쓴다","correct":true},{"t":"사물의 특징은 한 가지만 자세하게 쓴다","mis":"K2-2-u3-X01"},{"t":"사물을 설명하는 글에서는 생김새만 쓴다","mis":"K2-2-u3-X01"}],"explanation":["특징이 잘 드러나게요.","94쪽 예시 답안이에요.","여러 가지요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#10','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C1',2,'mc','auto','『국어』 94쪽 2번 — 옥수수를 설명하는 특징으로 알맞지 않은 것은?',ARRAY['K2-2-u3-X02']::text[],false,'{"seq":10,"concept":"K2-2-u3-C1","difficulty":2,"kind":"mc","stem":"『국어』 94쪽 2번 — 옥수수를 설명하는 특징으로 알맞지 않은 것은?","options":[{"t":"연주 방법","correct":true},{"t":"맛","mis":"K2-2-u3-X02"},{"t":"요리 방법","mis":"K2-2-u3-X02"}],"explanation":["옥수수는 악기가 아니에요.","94쪽 예시 답안이에요.","대상에 맞는 특징만요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#11','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C7',2,'match','auto','장소와 볼 수 있는 옷을 이어 보세요.','{}'::text[],false,'{"seq":11,"concept":"K2-2-u3-C7","difficulty":2,"kind":"match","stem":"장소와 볼 수 있는 옷을 이어 보세요.","pairs":[{"l":"수영장","r":"수영복"},{"l":"체육관이나 운동장","r":"운동복"},{"l":"결혼식장","r":"웨딩드레스"}],"mis":"K2-2-u3-X04","explanation":["장소에 따라 달라요.","84쪽이에요.","86쪽 (2)예요."],"asset":{"type":"passage","lines":["우리는 날마다 여러 가지 옷을 볼 수 있습니다.","친구들이 입는 옷에는 치마도 있고 바지도 있습니다.","또 친구들이 입는 옷의 색이나 무늬도 다양합니다.","어떤 장소인지에 따라서 볼 수 있는 옷이 달라집니다.","수영장에서는 수영복을, 체육관이나 운동장에서는","활동하기 편한 운동복을 많이 볼 수 있습니다.","결혼식장에서 볼 수 있는 특별한 옷은 웨딩드레스입니다."],"title":"『국어』 84쪽 「여러 가지 옷차림」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#12','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C1',2,'ox','auto','같은 물건도 여러 가지 특징으로 설명할 수 있어요.',ARRAY['K2-2-u3-X01']::text[],false,'{"seq":12,"concept":"K2-2-u3-C1","difficulty":2,"kind":"ox","stem":"같은 물건도 여러 가지 특징으로 설명할 수 있어요.","answer":"O","reason_options":[{"t":"모양·색깔·쓰임새처럼 물건마다 특징이 여러 가지 있으니까","correct":true},{"t":"물건마다 특징은 하나뿐이니까","mis":"K2-2-u3-X01"}],"mis":"K2-2-u3-X01","explanation":["여러 가지예요.","지도서 137쪽이에요.","다르게 설명해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#13','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C5',2,'mc','auto','『국어』 95쪽 — 「글자」의 내용을 알맞게 간추린 것은?',ARRAY['K2-2-u3-X07','K2-2-u3-X04']::text[],false,'{"seq":13,"concept":"K2-2-u3-C5","difficulty":2,"kind":"mc","stem":"『국어』 95쪽 — 「글자」의 내용을 알맞게 간추린 것은?","options":[{"t":"글자는 멀리 있는 사람이나 여러 사람에게 무언가를 알리기 편해요","correct":true},{"t":"말은 귀로 들어요","mis":"K2-2-u3-X07"},{"t":"가까이 있는 사람과는 말하지 않아요","mis":"K2-2-u3-X04"}],"explanation":["하고 싶은 말을 모았어요.","95쪽 예시 답안이에요.","내 말로 간추려요."],"asset":{"type":"passage","lines":["말은 귀로 듣고 글은 눈으로 보아요.","가까이 있는 사람들이 서로 뜻을 주고받는 데에는 말이 편해요.","그렇지만 멀리 있는 사람이나 여러 사람한테","무언가를 알리는 데에는 글이 더 편하지요.","그래서 아주 옛날부터 사람들은 글자를 썼어요."],"title":"『국어』 95쪽 「글자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
