INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#18','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C9',3,'error','auto','「제가 좋아하는 것은 연필입니다. 길쭉한 모양입니다. 제 짝은 키가 큽니다. 글씨를 쓸 때 씁니다.」
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#19','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C4',3,'mc','auto','「진심으로 사과하는 법을 알아 둬」의 중심 내용은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":19,"concept":"K2-2-u3-C4","difficulty":3,"kind":"mc","stem":"「진심으로 사과하는 법을 알아 둬」의 중심 내용은?","options":[{"t":"사과는 까닭을 말하고 정중하게, 변명 없이 진심으로 해야 한다","correct":true},{"t":"친구끼리는 사과하지 않아도 된다","mis":"K2-2-u3-X04"},{"t":"사과하면 선물을 준다","mis":"K2-2-u3-X04"}],"explanation":["하고 싶은 말이에요.","77쪽이에요.","한 문장으로요."],"asset":{"type":"passage","lines":["잘못했을 때는 상대에게 꼭 사과해야 해요.","마음속으로만 생각하면 상대는 알 수 없어요.","왜 미안한지 말하고, 다시는 그러지 않겠다고 약속해요.","받아 줄지는 상처받은 상대가 정해요.","그래서 「내 사과를 받아 줄래?」 하고 정중하게 물어봐요.","상대 잘못을 따지거나 「하지만…….」 하고 변명하지 않아요.","깨끗하게 잘못을 인정하고 진심으로 사과해요."],"title":"『국어』 74~75쪽 「진심으로 사과하는 법을 알아 둬」(박현숙) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#20','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C2',3,'mc','auto','지도서 161쪽 평가 — 제목 「최초의 악기는 무엇일까요」를 보고 짐작할 수 있는 내용은?',ARRAY['K2-2-u3-X03']::text[],false,'{"seq":20,"concept":"K2-2-u3-C2","difficulty":3,"kind":"mc","stem":"지도서 161쪽 평가 — 제목 「최초의 악기는 무엇일까요」를 보고 짐작할 수 있는 내용은?","options":[{"t":"처음 생긴 악기에 대한 이야기","correct":true},{"t":"악기를 파는 가게","mis":"K2-2-u3-X03"},{"t":"악기 고치는 방법","mis":"K2-2-u3-X03"}],"explanation":["제목에 있어요.","지도서 161쪽이에요.","읽고 확인해요."],"asset":{"type":"passage","lines":["처음에 사람들은 어떻게, 왜 음악을 만들기 시작했을까요?","최초의 악기라고 할 수 있는 것은 사람의 목소리예요.","오랫동안 부모는 부드러운 목소리로 아기를 재웠어요.","사람들은 함께 노래하며 같은 무리라는 것을 느꼈어요.","같은 노래를 함께 부르면 서로 친구로 이어지는 것 같아요."],"title":"지도서 161쪽 평가 자료 「최초의 악기는 무엇일까요」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#21','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C9',3,'mc','auto','지도서 163쪽 — ② 「뛰지 마시오」 표지판을 바르게 설명한 것은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":21,"concept":"K2-2-u3-C9","difficulty":3,"kind":"mc","stem":"지도서 163쪽 — ② 「뛰지 마시오」 표지판을 바르게 설명한 것은?","options":[{"t":"뛰어다니면 안 되는 곳임을 알려 줘요","correct":true},{"t":"넘어질 수 있으니 기대면 안 돼요","mis":"K2-2-u3-X04"},{"t":"재난이 나면 탈출하는 곳이에요","mis":"K2-2-u3-X04"}],"explanation":["뛰지 마시오예요.","지도서 163쪽이에요.","표지판과 뜻이 맞아야 해요."],"asset":{"type":"scene","icon":"🚫🧍 🚫🏃 🟩🚪","text":"① 기대지 마시오 ② 뛰지 마시오 ③ 비상구 — 지도서 163쪽 표지판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#22','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C5',3,'mc','auto','『국어활동』 33쪽 — 반달가슴곰이 주로 걷는 까닭은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":22,"concept":"K2-2-u3-C5","difficulty":3,"kind":"mc","stem":"『국어활동』 33쪽 — 반달가슴곰이 주로 걷는 까닭은?","options":[{"t":"몸집이 크고 무거워서","correct":true},{"t":"발가락이 없어서","mis":"K2-2-u3-X04"},{"t":"털이 많아서","mis":"K2-2-u3-X04"}],"explanation":["크고 무거워서요.","국어활동 33쪽 예시 답안이에요.","글에서 찾아요."],"asset":{"type":"passage","lines":["반달가슴곰의 발바닥은 크고 두껍고 털이 거의 없어요.","앞발과 뒷발 모두 발가락이 다섯 개예요.","몸집이 크고 무거워서 주로 걸어요."],"title":"『국어활동』 32~33쪽 「반달가슴곰 발자국」 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#23','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C1',4,'sa','auto','글에서 설명하는 물건이나 사람 따위를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u3-C1","difficulty":4,"kind":"sa","stem":"글에서 설명하는 물건이나 사람 따위를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["대상"],"explanation":["대상이에요.","86쪽이에요.","무엇을 설명하는지요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#24','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C4',4,'essay','teacher','지도서 161쪽 평가 — 「최초의 악기는 무엇일까요」에서 중요하다고 생각하는 문장을 하나 쓰고, 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u3-C4","difficulty":4,"kind":"essay","stem":"지도서 161쪽 평가 — 「최초의 악기는 무엇일까요」에서 중요하다고 생각하는 문장을 하나 쓰고, 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 최초의 악기라고 할 수 있는 것은 사람의 목소리예요. / 까닭: 제목이 최초의 악기를 묻고 있고, 그 답이 이 문장에 있어서예요.","scoring_points":["중요한 문장을 골랐어요","그렇게 생각한 까닭이 있어요"]},"explanation":["제목과 이어 봐요.","까닭을 써요.","지도서 160쪽이에요."],"asset":{"type":"passage","lines":["처음에 사람들은 어떻게, 왜 음악을 만들기 시작했을까요?","최초의 악기라고 할 수 있는 것은 사람의 목소리예요.","오랫동안 부모는 부드러운 목소리로 아기를 재웠어요.","사람들은 함께 노래하며 같은 무리라는 것을 느꼈어요.","같은 노래를 함께 부르면 서로 친구로 이어지는 것 같아요."],"title":"지도서 161쪽 평가 자료 「최초의 악기는 무엇일까요」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_a#25','kor',2,2,'u3','','g2_2_kor_u3_review_a','unit_review','K2-2-u3-C9',4,'essay','teacher','지도서 163쪽 평가 — 표지판 ①~③ 가운데 하나를 골라 이름(뜻)과 모양을 넣어 설명하는 글을 세 문장 이상 쓰세요. 「제가 고른 표지판은 ( )번입니다.」로 시작하세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u3-C9","difficulty":4,"kind":"essay","stem":"지도서 163쪽 평가 — 표지판 ①~③ 가운데 하나를 골라 이름(뜻)과 모양을 넣어 설명하는 글을 세 문장 이상 쓰세요. 「제가 고른 표지판은 ( )번입니다.」로 시작하세요.","answer_guide":{"answer":"예: 제가 고른 표지판은 ③번입니다. 이 표지판은 비상구입니다. 초록색 네모 안에 문으로 달려가는 사람이 그려져 있습니다. 재난 사고가 일어나면 이곳으로 탈출합니다.","scoring_points":["고른 표지판과 이름·뜻이 맞아요","모양을 썼어요","세 문장 이상이에요"]},"explanation":["표지판을 하나 골라요.","사실을 써요.","지도서 162쪽이에요."],"asset":{"type":"scene","icon":"🚫🧍 🚫🏃 🟩🚪","text":"① 기대지 마시오 ② 뛰지 마시오 ③ 비상구 — 지도서 163쪽 표지판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#1','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C1',1,'mc','auto','유정이가 「동그란 모양」이라고만 했더니 친구들은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":1,"concept":"K2-2-u3-C1","difficulty":1,"kind":"mc","stem":"유정이가 「동그란 모양」이라고만 했더니 친구들은?","options":[{"t":"시계·물병·농구공처럼 각각 다른 물건을 떠올렸어요","correct":true},{"t":"모두 시계를 떠올렸어요","mis":"K2-2-u3-X04"},{"t":"아무것도 떠올리지 않았어요","mis":"K2-2-u3-X04"}],"explanation":["다른 물건을 떠올렸어요.","73쪽이에요.","동그란 것은 많아요."],"asset":{"type":"speech","turns":[{"who":"유정","text":"이 물건은 동그란 모양입니다."},{"who":"친구들","text":"(저마다 다른 물건을 떠올려요) 시계? 농구공? 물병?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#2','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C3',1,'mc','auto','사과할 때 상대에게 정중하게 묻는 말은?',ARRAY['K2-2-u3-X08']::text[],false,'{"seq":2,"concept":"K2-2-u3-C3","difficulty":1,"kind":"mc","stem":"사과할 때 상대에게 정중하게 묻는 말은?","options":[{"t":"「내 사과를 받아 줄래?」","correct":true},{"t":"「됐지?」","mis":"K2-2-u3-X08"},{"t":"「빨리 받아.」","mis":"K2-2-u3-X08"}],"explanation":["정중하게 물어요.","76쪽이에요.","상대가 정해요."],"asset":{"type":"passage","lines":["잘못했을 때는 상대에게 꼭 사과해야 해요.","마음속으로만 생각하면 상대는 알 수 없어요.","왜 미안한지 말하고, 다시는 그러지 않겠다고 약속해요.","받아 줄지는 상처받은 상대가 정해요.","그래서 「내 사과를 받아 줄래?」 하고 정중하게 물어봐요.","상대 잘못을 따지거나 「하지만…….」 하고 변명하지 않아요.","깨끗하게 잘못을 인정하고 진심으로 사과해요."],"title":"『국어』 74~75쪽 「진심으로 사과하는 법을 알아 둬」(박현숙) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#3','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C5',1,'mc','auto','수수로 만든 빗자루의 이름은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":3,"concept":"K2-2-u3-C5","difficulty":1,"kind":"mc","stem":"수수로 만든 빗자루의 이름은?","options":[{"t":"장목비","correct":true},{"t":"싸리비","mis":"K2-2-u3-X04"},{"t":"솔비","mis":"K2-2-u3-X04"}],"explanation":["장목비예요.","80쪽이에요.","재료가 이름이 돼요."],"asset":{"type":"passage","lines":["빗자루는 먼지나 쓰레기를 쓸어 모으는 청소 도구예요.","수수·갈대·댑싸리·대나무 같은 것을 묶어 만들어요.","먼저 줄기를 소금물에 삶아 그늘에 말리고, 나락·꽃가루를 긁어내요.","줄기를 가지런히 묶은 뒤 끝을 가지런히 잘라요.","재료나 생김새에 따라 이름이 달라요.","싸리비(싸리) · 장목비(수수) · 갈목비(갈대 이삭)","대장 비(대나무 손잡이) · 솔비(솔가지) · 꽃비(수 놓은 방비)","옛날에는 빗자루로 인형 놀이도 했어요."],"title":"『국어』 78~80쪽 「빗자루」(윤혜신) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#4','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C7',1,'mc','auto','체육관이나 운동장에서 많이 볼 수 있는 옷은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":4,"concept":"K2-2-u3-C7","difficulty":1,"kind":"mc","stem":"체육관이나 운동장에서 많이 볼 수 있는 옷은?","options":[{"t":"활동하기 편한 운동복","correct":true},{"t":"웨딩드레스","mis":"K2-2-u3-X04"},{"t":"요리용 모자","mis":"K2-2-u3-X04"}],"explanation":["운동복이에요.","84쪽이에요.","장소에 따라요."],"asset":{"type":"passage","lines":["우리는 날마다 여러 가지 옷을 볼 수 있습니다.","친구들이 입는 옷에는 치마도 있고 바지도 있습니다.","또 친구들이 입는 옷의 색이나 무늬도 다양합니다.","어떤 장소인지에 따라서 볼 수 있는 옷이 달라집니다.","수영장에서는 수영복을, 체육관이나 운동장에서는","활동하기 편한 운동복을 많이 볼 수 있습니다.","결혼식장에서 볼 수 있는 특별한 옷은 웨딩드레스입니다."],"title":"『국어』 84쪽 「여러 가지 옷차림」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#5','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C8',1,'mc','auto','『국어』 98쪽 2번 — 알맞은 낱말은?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#6','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C2',1,'mc','auto','제목을 보고 짐작하기 — 「빗자루」는 무엇에 대한 글일까요?',ARRAY['K2-2-u3-X03']::text[],false,'{"seq":6,"concept":"K2-2-u3-C2","difficulty":1,"kind":"mc","stem":"제목을 보고 짐작하기 — 「빗자루」는 무엇에 대한 글일까요?","options":[{"t":"빗자루","correct":true},{"t":"마법사","mis":"K2-2-u3-X03"},{"t":"인형","mis":"K2-2-u3-X03"}],"explanation":["빗자루예요.","82쪽이에요.","제목이 대상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
