INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#11','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C6',2,'match','auto','뜻이 반대인 낱말을 이어 보세요.','{}'::text[],false,'{"seq":11,"concept":"K2-2-u3-C6","difficulty":2,"kind":"match","stem":"뜻이 반대인 낱말을 이어 보세요.","pairs":[{"l":"묶어","r":"풀어"},{"l":"질겨져","r":"연해져"},{"l":"가지런히","r":"들쭉날쭉"}],"mis":"K2-2-u3-X09","explanation":["반대말이에요.","81쪽이에요.","문장에 넣어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#12','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C3',2,'ox','auto','사과할 때 「미안해. 하지만…….」 하고 변명하면 더 좋아요.',ARRAY['K2-2-u3-X08']::text[],false,'{"seq":12,"concept":"K2-2-u3-C3","difficulty":2,"kind":"ox","stem":"사과할 때 「미안해. 하지만…….」 하고 변명하면 더 좋아요.","answer":"X","reason_options":[{"t":"변명하다 보면 상대를 탓하게 되니까","correct":true},{"t":"이유를 말해야 공평하니까","mis":"K2-2-u3-X08"}],"mis":"K2-2-u3-X08","explanation":["변명하지 않아요.","75쪽이에요.","딱 사과만요."],"asset":{"type":"passage","lines":["잘못했을 때는 상대에게 꼭 사과해야 해요.","마음속으로만 생각하면 상대는 알 수 없어요.","왜 미안한지 말하고, 다시는 그러지 않겠다고 약속해요.","받아 줄지는 상처받은 상대가 정해요.","그래서 「내 사과를 받아 줄래?」 하고 정중하게 물어봐요.","상대 잘못을 따지거나 「하지만…….」 하고 변명하지 않아요.","깨끗하게 잘못을 인정하고 진심으로 사과해요."],"title":"『국어』 74~75쪽 「진심으로 사과하는 법을 알아 둬」(박현숙) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#13','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C5',2,'mc','auto','「글자」에서 가까이 있는 사람과 뜻을 주고받을 때 편한 것은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":13,"concept":"K2-2-u3-C5","difficulty":2,"kind":"mc","stem":"「글자」에서 가까이 있는 사람과 뜻을 주고받을 때 편한 것은?","options":[{"t":"말","correct":true},{"t":"글","mis":"K2-2-u3-X04"},{"t":"그림","mis":"K2-2-u3-X04"}],"explanation":["말이에요.","95쪽이에요.","멀면 글이에요."],"asset":{"type":"passage","lines":["말은 귀로 듣고 글은 눈으로 보아요.","가까이 있는 사람들이 서로 뜻을 주고받는 데에는 말이 편해요.","그렇지만 멀리 있는 사람이나 여러 사람한테","무언가를 알리는 데에는 글이 더 편하지요.","그래서 아주 옛날부터 사람들은 글자를 썼어요."],"title":"『국어』 95쪽 「글자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
