INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#18','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C7',3,'error','auto','「수영장에서는 수영복을 입습니다. 수영복은 촌스럽습니다. 결혼식장에서는 웨딩드레스를 볼 수 있습니다.」
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#19','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C5',3,'mc','auto','「빗자루」를 간추린 것으로 알맞은 것은?',ARRAY['K2-2-u3-X07']::text[],false,'{"seq":19,"concept":"K2-2-u3-C5","difficulty":3,"kind":"mc","stem":"「빗자루」를 간추린 것으로 알맞은 것은?","options":[{"t":"빗자루는 청소 도구로, 줄기를 삶고 말려 묶어 만들며, 재료나 생김새에 따라 이름이 달라요","correct":true},{"t":"서양에는 빗자루를 타는 마법사가 있어요","mis":"K2-2-u3-X07"},{"t":"대나무로 만든 빗자루는 손잡이가 길어요","mis":"K2-2-u3-X07"}],"explanation":["중요한 내용을 이었어요.","83쪽이에요.","짧게 모아요."],"asset":{"type":"passage","lines":["빗자루는 먼지나 쓰레기를 쓸어 모으는 청소 도구예요.","수수·갈대·댑싸리·대나무 같은 것을 묶어 만들어요.","먼저 줄기를 소금물에 삶아 그늘에 말리고, 나락·꽃가루를 긁어내요.","줄기를 가지런히 묶은 뒤 끝을 가지런히 잘라요.","재료나 생김새에 따라 이름이 달라요.","싸리비(싸리) · 장목비(수수) · 갈목비(갈대 이삭)","대장 비(대나무 손잡이) · 솔비(솔가지) · 꽃비(수 놓은 방비)","옛날에는 빗자루로 인형 놀이도 했어요."],"title":"『국어』 78~80쪽 「빗자루」(윤혜신) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#20','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C5',3,'mc','auto','지도서 161쪽 — 이 글에서 「최초의 악기」라고 한 것은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":20,"concept":"K2-2-u3-C5","difficulty":3,"kind":"mc","stem":"지도서 161쪽 — 이 글에서 「최초의 악기」라고 한 것은?","options":[{"t":"사람의 목소리","correct":true},{"t":"북","mis":"K2-2-u3-X04"},{"t":"피리","mis":"K2-2-u3-X04"}],"explanation":["목소리예요.","지도서 161쪽이에요.","글에서 찾아요."],"asset":{"type":"passage","lines":["처음에 사람들은 어떻게, 왜 음악을 만들기 시작했을까요?","최초의 악기라고 할 수 있는 것은 사람의 목소리예요.","오랫동안 부모는 부드러운 목소리로 아기를 재웠어요.","사람들은 함께 노래하며 같은 무리라는 것을 느꼈어요.","같은 노래를 함께 부르면 서로 친구로 이어지는 것 같아요."],"title":"지도서 161쪽 평가 자료 「최초의 악기는 무엇일까요」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#21','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C9',3,'mc','auto','지도서 163쪽 — ③ 「비상구」 표지판을 바르게 설명한 것은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":21,"concept":"K2-2-u3-C9","difficulty":3,"kind":"mc","stem":"지도서 163쪽 — ③ 「비상구」 표지판을 바르게 설명한 것은?","options":[{"t":"재난 사고가 일어나면 비상구로 탈출해요","correct":true},{"t":"뛰어다니면 안 돼요","mis":"K2-2-u3-X04"},{"t":"기대면 안 돼요","mis":"K2-2-u3-X04"}],"explanation":["비상구예요.","지도서 163쪽이에요.","초록색 표지판이에요."],"asset":{"type":"scene","icon":"🚫🧍 🚫🏃 🟩🚪","text":"① 기대지 마시오 ② 뛰지 마시오 ③ 비상구 — 지도서 163쪽 표지판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#22','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C5',3,'mc','auto','『국어활동』 33쪽 — 반달가슴곰의 발바닥은 어떠한가요?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":22,"concept":"K2-2-u3-C5","difficulty":3,"kind":"mc","stem":"『국어활동』 33쪽 — 반달가슴곰의 발바닥은 어떠한가요?","options":[{"t":"크고 두꺼우며 털이 거의 없어요","correct":true},{"t":"작고 털이 많아요","mis":"K2-2-u3-X04"},{"t":"발바닥이 없어요","mis":"K2-2-u3-X04"}],"explanation":["크고 두꺼워요.","국어활동 33쪽이에요.","털이 거의 없어요."],"asset":{"type":"passage","lines":["반달가슴곰의 발바닥은 크고 두껍고 털이 거의 없어요.","앞발과 뒷발 모두 발가락이 다섯 개예요.","몸집이 크고 무거워서 주로 걸어요."],"title":"『국어활동』 32~33쪽 「반달가슴곰 발자국」 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#23','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C4',4,'sa','auto','글을 읽기 전에 무슨 내용일지 짐작하려고 보는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u3-C4","difficulty":4,"kind":"sa","stem":"글을 읽기 전에 무슨 내용일지 짐작하려고 보는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["제목"],"explanation":["제목이에요.","77쪽 4번이에요.","짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#24','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C5',4,'essay','teacher','『국어』 95쪽 「글자」를 읽고 「이 글은 ○○을/를 설명하고 있습니다.」로 시작해 내용을 간추려 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u3-C5","difficulty":4,"kind":"essay","stem":"『국어』 95쪽 「글자」를 읽고 「이 글은 ○○을/를 설명하고 있습니다.」로 시작해 내용을 간추려 쓰세요.","answer_guide":{"answer":"예: 이 글은 글자를 설명하고 있습니다. 글자는 멀리 있는 사람이나 여러 사람에게 무언가를 알리기 편합니다.","scoring_points":["대상을 썼어요","중심 내용을 간추렸어요"]},"explanation":["대상을 먼저 써요.","하고 싶은 말을 모아요.","95쪽 예시 답안이에요."],"asset":{"type":"passage","lines":["말은 귀로 듣고 글은 눈으로 보아요.","가까이 있는 사람들이 서로 뜻을 주고받는 데에는 말이 편해요.","그렇지만 멀리 있는 사람이나 여러 사람한테","무언가를 알리는 데에는 글이 더 편하지요.","그래서 아주 옛날부터 사람들은 글자를 썼어요."],"title":"『국어』 95쪽 「글자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_b#25','kor',2,2,'u3','','g2_2_kor_u3_review_b','unit_review','K2-2-u3-C9',4,'essay','teacher','내가 좋아하는 물건 하나를 골라 대상과 특징이 드러나게 세 문장 이상으로 설명하는 글을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u3-C9","difficulty":4,"kind":"essay","stem":"내가 좋아하는 물건 하나를 골라 대상과 특징이 드러나게 세 문장 이상으로 설명하는 글을 쓰세요.","answer_guide":{"answer":"예: 제가 좋아하는 것은 필통입니다. 필통은 네모난 모양이고 하늘색입니다. 연필과 지우개를 넣어 다닙니다.","scoring_points":["대상이 있어요","특징이 여러 가지예요","세 문장 이상이에요"]},"explanation":["대상을 먼저요.","특징을 여러 가지요.","90쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_c#1','kor',2,2,'u3','','g2_2_kor_u3_review_c','unit_review','K2-2-u3-C1',1,'mc','auto','「얼굴에 숫자가 있고 시간을 알려 줘요.」는 무엇의 특징인가요?',ARRAY['K2-2-u3-X01']::text[],false,'{"seq":1,"concept":"K2-2-u3-C1","difficulty":1,"kind":"mc","stem":"「얼굴에 숫자가 있고 시간을 알려 줘요.」는 무엇의 특징인가요?","options":[{"t":"시계","correct":true},{"t":"물병","mis":"K2-2-u3-X01"},{"t":"농구공","mis":"K2-2-u3-X01"}],"explanation":["시계예요.","지도서 151쪽이에요.","특징으로 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_c#2','kor',2,2,'u3','','g2_2_kor_u3_review_c','unit_review','K2-2-u3-C3',1,'mc','auto','진심으로 사과할 때 함께 말하면 좋은 것은?',ARRAY['K2-2-u3-X08','K2-2-u3-X04']::text[],false,'{"seq":2,"concept":"K2-2-u3-C3","difficulty":1,"kind":"mc","stem":"진심으로 사과할 때 함께 말하면 좋은 것은?","options":[{"t":"왜 미안한지","correct":true},{"t":"상대가 잘못한 점","mis":"K2-2-u3-X08"},{"t":"다른 친구 이야기","mis":"K2-2-u3-X04"}],"explanation":["미안한 까닭이에요.","74쪽이에요.","약속도 해요."],"asset":{"type":"passage","lines":["잘못했을 때는 상대에게 꼭 사과해야 해요.","마음속으로만 생각하면 상대는 알 수 없어요.","왜 미안한지 말하고, 다시는 그러지 않겠다고 약속해요.","받아 줄지는 상처받은 상대가 정해요.","그래서 「내 사과를 받아 줄래?」 하고 정중하게 물어봐요.","상대 잘못을 따지거나 「하지만…….」 하고 변명하지 않아요.","깨끗하게 잘못을 인정하고 진심으로 사과해요."],"title":"『국어』 74~75쪽 「진심으로 사과하는 법을 알아 둬」(박현숙) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_c#3','kor',2,2,'u3','','g2_2_kor_u3_review_c','unit_review','K2-2-u3-C5',1,'mc','auto','빗자루를 만드는 재료로 글에 나온 것은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":3,"concept":"K2-2-u3-C5","difficulty":1,"kind":"mc","stem":"빗자루를 만드는 재료로 글에 나온 것은?","options":[{"t":"갈대","correct":true},{"t":"비닐","mis":"K2-2-u3-X04"},{"t":"쇠","mis":"K2-2-u3-X04"}],"explanation":["갈대예요.","78쪽이에요.","수수·싸리·대나무도요."],"asset":{"type":"passage","lines":["빗자루는 먼지나 쓰레기를 쓸어 모으는 청소 도구예요.","수수·갈대·댑싸리·대나무 같은 것을 묶어 만들어요.","먼저 줄기를 소금물에 삶아 그늘에 말리고, 나락·꽃가루를 긁어내요.","줄기를 가지런히 묶은 뒤 끝을 가지런히 잘라요.","재료나 생김새에 따라 이름이 달라요.","싸리비(싸리) · 장목비(수수) · 갈목비(갈대 이삭)","대장 비(대나무 손잡이) · 솔비(솔가지) · 꽃비(수 놓은 방비)","옛날에는 빗자루로 인형 놀이도 했어요."],"title":"『국어』 78~80쪽 「빗자루」(윤혜신) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_c#4','kor',2,2,'u3','','g2_2_kor_u3_review_c','unit_review','K2-2-u3-C7',1,'mc','auto','요리하는 사람이 두르는 것은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":4,"concept":"K2-2-u3-C7","difficulty":1,"kind":"mc","stem":"요리하는 사람이 두르는 것은?","options":[{"t":"앞치마","correct":true},{"t":"헬멧","mis":"K2-2-u3-X04"},{"t":"수영복","mis":"K2-2-u3-X04"}],"explanation":["앞치마예요.","85쪽이에요.","하는 일에 따라요."],"asset":{"type":"passage","lines":["하는 일에 따라서도 옷차림이 달라집니다.","소방관은 뜨거운 불로부터 몸을 보호하려고","헬멧과 장갑, 열을 막을 수 있는 특별한 옷을 입습니다.","요리하는 사람은 음식을 청결하게 만들려고","요리용 모자를 쓰거나 앞치마를 두릅니다."],"title":"『국어』 85쪽 「여러 가지 옷차림」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
