INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_c#19','kor',2,2,'u3','','g2_2_kor_u3_review_c','unit_review','K2-2-u3-C5',3,'mc','auto','「여러 가지 옷차림」의 중심 내용은?',ARRAY['K2-2-u3-X07']::text[],false,'{"seq":19,"concept":"K2-2-u3-C5","difficulty":3,"kind":"mc","stem":"「여러 가지 옷차림」의 중심 내용은?","options":[{"t":"옷차림은 장소와 하는 일에 따라 달라진다","correct":true},{"t":"소방관은 장갑을 낀다","mis":"K2-2-u3-X07"},{"t":"친구들은 치마를 입는다","mis":"K2-2-u3-X07"}],"explanation":["장소·하는 일이에요.","86쪽이에요.","작은 내용은 예예요."],"asset":{"type":"passage","lines":["하는 일에 따라서도 옷차림이 달라집니다.","소방관은 뜨거운 불로부터 몸을 보호하려고","헬멧과 장갑, 열을 막을 수 있는 특별한 옷을 입습니다.","요리하는 사람은 음식을 청결하게 만들려고","요리용 모자를 쓰거나 앞치마를 두릅니다."],"title":"『국어』 85쪽 「여러 가지 옷차림」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_c#20','kor',2,2,'u3','','g2_2_kor_u3_review_c','unit_review','K2-2-u3-C4',3,'mc','auto','지도서 161쪽 — 이 글의 중심 내용으로 알맞은 것은?',ARRAY['K2-2-u3-X07']::text[],false,'{"seq":20,"concept":"K2-2-u3-C4","difficulty":3,"kind":"mc","stem":"지도서 161쪽 — 이 글의 중심 내용으로 알맞은 것은?","options":[{"t":"최초의 악기는 사람의 목소리이고, 함께 노래하면 서로 이어진다","correct":true},{"t":"아기는 잠을 많이 잔다","mis":"K2-2-u3-X07"},{"t":"사람들은 줄을 서서 걷는다","mis":"K2-2-u3-X07"}],"explanation":["하고 싶은 말이에요.","지도서 160쪽이에요.","작은 내용은 빼요."],"asset":{"type":"passage","lines":["처음에 사람들은 어떻게, 왜 음악을 만들기 시작했을까요?","최초의 악기라고 할 수 있는 것은 사람의 목소리예요.","오랫동안 부모는 부드러운 목소리로 아기를 재웠어요.","사람들은 함께 노래하며 같은 무리라는 것을 느꼈어요.","같은 노래를 함께 부르면 서로 친구로 이어지는 것 같아요."],"title":"지도서 161쪽 평가 자료 「최초의 악기는 무엇일까요」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_c#21','kor',2,2,'u3','','g2_2_kor_u3_review_c','unit_review','K2-2-u3-C9',3,'mc','auto','지도서 162쪽 — 표지판을 설명하는 글에서 꼭 지켜야 할 것은?',ARRAY['K2-2-u3-X01','K2-2-u3-X11']::text[],false,'{"seq":21,"concept":"K2-2-u3-C9","difficulty":3,"kind":"mc","stem":"지도서 162쪽 — 표지판을 설명하는 글에서 꼭 지켜야 할 것은?","options":[{"t":"고른 표지판과 이름·뜻이 서로 맞아야 해요","correct":true},{"t":"표지판을 그리기만 해요","mis":"K2-2-u3-X01"},{"t":"내가 좋아하는 표지판이라고만 써요","mis":"K2-2-u3-X11"}],"explanation":["객관적인 정보예요.","지도서 162쪽이에요.","표지판과 뜻을 맞춰요."],"asset":{"type":"scene","icon":"🚫🧍 🚫🏃 🟩🚪","text":"① 기대지 마시오 ② 뛰지 마시오 ③ 비상구 — 지도서 163쪽 표지판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_c#22','kor',2,2,'u3','','g2_2_kor_u3_review_c','unit_review','K2-2-u3-C5',3,'mc','auto','『국어활동』 35쪽 — 「모」는 언제인가요?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":22,"concept":"K2-2-u3-C5","difficulty":3,"kind":"mc","stem":"『국어활동』 35쪽 — 「모」는 언제인가요?","options":[{"t":"평평한 부분이 하나도 안 나올 때","correct":true},{"t":"평평한 부분이 한 개 나올 때","mis":"K2-2-u3-X04"},{"t":"평평한 부분이 세 개 나올 때","mis":"K2-2-u3-X04"}],"explanation":["하나도 안 나올 때예요.","국어활동 35쪽 예시 답안이에요.","말의 방언이에요."],"asset":{"type":"passage","lines":["윷놀이에서는 윷가락 네 개를 던져요.","평평한 부분이 몇 개 나오느냐에 따라 도·개·걸·윷·모가 정해져요.","도: 평평한 부분이 한 개 — 돼지를 가리키는 옛말","걸: 평평한 부분이 세 개 — 양을 가리키는 옛말","모: 평평한 부분이 하나도 안 나올 때 — 말의 방언"],"title":"『국어활동』 34~35쪽 「도, 개, 걸, 윷, 모의 말뜻」 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_c#23','kor',2,2,'u3','','g2_2_kor_u3_review_c','unit_review','K2-2-u3-C8',4,'sa','auto','「강아지가 내 볼을 (     ) 깜짝 놀랐어.」 빈칸에 알맞은 낱말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u3-C8","difficulty":4,"kind":"sa","stem":"「강아지가 내 볼을 (     ) 깜짝 놀랐어.」 빈칸에 알맞은 낱말을 쓰세요.","answer":["핥아서"],"explanation":["핥아서예요.","98쪽이에요.","겹받침 ㄾ이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_c#24','kor',2,2,'u3','','g2_2_kor_u3_review_c','unit_review','K2-2-u3-C5',4,'essay','teacher','「빗자루」의 중심 내용을 두세 문장으로 간추려 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u3-C5","difficulty":4,"kind":"essay","stem":"「빗자루」의 중심 내용을 두세 문장으로 간추려 쓰세요.","answer_guide":{"answer":"예: 빗자루는 먼지나 쓰레기를 쓸어 모으는 청소 도구다. 줄기를 삶고 말려 가지런히 묶어 만든다. 재료나 생김새에 따라 이름이 달라진다.","scoring_points":["쓰임새가 있어요","만드는 방법이나 이름이 있어요","작은 내용은 뺐어요"]},"explanation":["덩어리마다 중심 내용이요.","이어서 써요.","83쪽이에요."],"asset":{"type":"passage","lines":["빗자루는 먼지나 쓰레기를 쓸어 모으는 청소 도구예요.","수수·갈대·댑싸리·대나무 같은 것을 묶어 만들어요.","먼저 줄기를 소금물에 삶아 그늘에 말리고, 나락·꽃가루를 긁어내요.","줄기를 가지런히 묶은 뒤 끝을 가지런히 잘라요.","재료나 생김새에 따라 이름이 달라요.","싸리비(싸리) · 장목비(수수) · 갈목비(갈대 이삭)","대장 비(대나무 손잡이) · 솔비(솔가지) · 꽃비(수 놓은 방비)","옛날에는 빗자루로 인형 놀이도 했어요."],"title":"『국어』 78~80쪽 「빗자루」(윤혜신) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_c#25','kor',2,2,'u3','','g2_2_kor_u3_review_c','unit_review','K2-2-u3-C7',4,'essay','teacher','『국어활동』 37쪽처럼 좋아하는 음식 하나를 골라 이름·모양 또는 색깔·맛·재료를 넣어 설명하는 글을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u3-C7","difficulty":4,"kind":"essay","stem":"『국어활동』 37쪽처럼 좋아하는 음식 하나를 골라 이름·모양 또는 색깔·맛·재료를 넣어 설명하는 글을 쓰세요.","answer_guide":{"answer":"예: 제가 좋아하는 음식은 김밥입니다. 김밥은 동그랗게 썰려 있고 겉은 까만색입니다. 고소한 맛이 납니다. 밥, 김, 달걀, 단무지로 만듭니다.","scoring_points":["음식 이름이 있어요","특징이 세 가지 이상이에요","문장으로 썼어요"]},"explanation":["칸을 채우듯 써요.","문장으로 이어요.","국어활동 37쪽이에요."],"asset":{"type":"passage","lines":["음식 이름: 떡볶이","모양 또는 색깔: 떡이나 어묵이 길쭉하다. / 빨간색","맛: 매콤하다.","재료: 떡, 어묵, 고추장 등"],"title":"『국어활동』 37쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#1','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C1',1,'mc','auto','『국어』 94쪽 2번 — 옥수수의 특징으로 알맞은 것은?',ARRAY['K2-2-u3-X02']::text[],false,'{"seq":1,"concept":"K2-2-u3-C1","difficulty":1,"kind":"mc","stem":"『국어』 94쪽 2번 — 옥수수의 특징으로 알맞은 것은?","options":[{"t":"노란 색깔과 생김새","correct":true},{"t":"연주 방법","mis":"K2-2-u3-X02"},{"t":"놀이 방법","mis":"K2-2-u3-X02"}],"explanation":["색깔·생김새예요.","94쪽 예시 답안이에요.","이름·맛·요리 방법도요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#2','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C3',1,'mc','auto','사과하는 말로 알맞은 것은?',ARRAY['K2-2-u3-X08']::text[],false,'{"seq":2,"concept":"K2-2-u3-C3","difficulty":1,"kind":"mc","stem":"사과하는 말로 알맞은 것은?","options":[{"t":"미안해. 다시는 그러지 않을게.","correct":true},{"t":"미안해. 하지만 너도 잘못했어.","mis":"K2-2-u3-X08"},{"t":"미안하다고 했잖아.","mis":"K2-2-u3-X08"}],"explanation":["변명·따지기 없이요.","75쪽이에요.","약속을 해요."],"asset":{"type":"passage","lines":["잘못했을 때는 상대에게 꼭 사과해야 해요.","마음속으로만 생각하면 상대는 알 수 없어요.","왜 미안한지 말하고, 다시는 그러지 않겠다고 약속해요.","받아 줄지는 상처받은 상대가 정해요.","그래서 「내 사과를 받아 줄래?」 하고 정중하게 물어봐요.","상대 잘못을 따지거나 「하지만…….」 하고 변명하지 않아요.","깨끗하게 잘못을 인정하고 진심으로 사과해요."],"title":"『국어』 74~75쪽 「진심으로 사과하는 법을 알아 둬」(박현숙) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#3','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C5',1,'mc','auto','빗자루로 한 놀이로 글에 나온 것은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":3,"concept":"K2-2-u3-C5","difficulty":1,"kind":"mc","stem":"빗자루로 한 놀이로 글에 나온 것은?","options":[{"t":"인형 놀이","correct":true},{"t":"공놀이","mis":"K2-2-u3-X04"},{"t":"숨바꼭질","mis":"K2-2-u3-X04"}],"explanation":["인형 놀이예요.","80쪽이에요.","81쪽 (4)예요."],"asset":{"type":"passage","lines":["빗자루는 먼지나 쓰레기를 쓸어 모으는 청소 도구예요.","수수·갈대·댑싸리·대나무 같은 것을 묶어 만들어요.","먼저 줄기를 소금물에 삶아 그늘에 말리고, 나락·꽃가루를 긁어내요.","줄기를 가지런히 묶은 뒤 끝을 가지런히 잘라요.","재료나 생김새에 따라 이름이 달라요.","싸리비(싸리) · 장목비(수수) · 갈목비(갈대 이삭)","대장 비(대나무 손잡이) · 솔비(솔가지) · 꽃비(수 놓은 방비)","옛날에는 빗자루로 인형 놀이도 했어요."],"title":"『국어』 78~80쪽 「빗자루」(윤혜신) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#4','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C7',1,'mc','auto','날씨가 추울 때 입는 옷은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":4,"concept":"K2-2-u3-C7","difficulty":1,"kind":"mc","stem":"날씨가 추울 때 입는 옷은?","options":[{"t":"두께가 두껍고 소매가 긴 옷","correct":true},{"t":"두께가 얇고 소매가 짧은 옷","mis":"K2-2-u3-X04"},{"t":"비옷만","mis":"K2-2-u3-X04"}],"explanation":["두껍고 긴 옷이에요.","87쪽이에요.","날씨에 따라요."],"asset":{"type":"passage","lines":["날씨에 따라서 입는 옷이 달라지기도 합니다.","날씨가 더울 때에는 두께가 얇고, 소매가 짧은 옷을 입습니다.","날씨가 추울 때에는 두께가 두껍고, 소매가 긴 옷을 입습니다.","비가 오는 날에는 비옷을 입고 장화를 신기도 합니다."],"title":"『국어』 87쪽 4번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
