INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#11','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C5',2,'match','auto','『국어활동』 35쪽 — 윷의 이름과 이름을 따온 동물을 이어 보세요.','{}'::text[],false,'{"seq":11,"concept":"K2-2-u3-C5","difficulty":2,"kind":"match","stem":"『국어활동』 35쪽 — 윷의 이름과 이름을 따온 동물을 이어 보세요.","pairs":[{"l":"도","r":"돼지"},{"l":"걸","r":"양"},{"l":"모","r":"말"}],"mis":"K2-2-u3-X04","explanation":["옛말·방언에서 왔어요.","국어활동 35쪽이에요.","설명하는 글이에요."],"asset":{"type":"passage","lines":["윷놀이에서는 윷가락 네 개를 던져요.","평평한 부분이 몇 개 나오느냐에 따라 도·개·걸·윷·모가 정해져요.","도: 평평한 부분이 한 개 — 돼지를 가리키는 옛말","걸: 평평한 부분이 세 개 — 양을 가리키는 옛말","모: 평평한 부분이 하나도 안 나올 때 — 말의 방언"],"title":"『국어활동』 34~35쪽 「도, 개, 걸, 윷, 모의 말뜻」 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#12','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C7',2,'ox','auto','설명하는 글에는 누구나 알 수 있는 사실을 써요.',ARRAY['K2-2-u3-X11']::text[],false,'{"seq":12,"concept":"K2-2-u3-C7","difficulty":2,"kind":"ox","stem":"설명하는 글에는 누구나 알 수 있는 사실을 써요.","answer":"O","reason_options":[{"t":"설명하는 글은 대상을 알려 주는 글이니까","correct":true},{"t":"내 느낌만 쓰면 되니까","mis":"K2-2-u3-X11"}],"mis":"K2-2-u3-X11","explanation":["사실을 써요.","지도서 135쪽이에요.","좋고 나쁨은 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#13','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C5',2,'mc','auto','『국어활동』 35쪽 — 도·개·걸·윷·모는 무엇에 따라 정해지나요?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":13,"concept":"K2-2-u3-C5","difficulty":2,"kind":"mc","stem":"『국어활동』 35쪽 — 도·개·걸·윷·모는 무엇에 따라 정해지나요?","options":[{"t":"윷가락의 평평한 부분이 몇 개 나오는지에 따라","correct":true},{"t":"윷가락의 색깔에 따라","mis":"K2-2-u3-X04"},{"t":"던진 사람의 나이에 따라","mis":"K2-2-u3-X04"}],"explanation":["평평한 부분의 개수예요.","국어활동 35쪽 예시 답안이에요.","중심 내용이에요."],"asset":{"type":"passage","lines":["윷놀이에서는 윷가락 네 개를 던져요.","평평한 부분이 몇 개 나오느냐에 따라 도·개·걸·윷·모가 정해져요.","도: 평평한 부분이 한 개 — 돼지를 가리키는 옛말","걸: 평평한 부분이 세 개 — 양을 가리키는 옛말","모: 평평한 부분이 하나도 안 나올 때 — 말의 방언"],"title":"『국어활동』 34~35쪽 「도, 개, 걸, 윷, 모의 말뜻」 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
