INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#16','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C4',2,'mc','auto','빗자루 글에서 「빗자루를 어떻게 만드는지 아니?」로 시작하는 덩어리의 중심 내용은?',ARRAY['K2-2-u3-X07']::text[],false,'{"seq":16,"concept":"K2-2-u3-C4","difficulty":2,"kind":"mc","stem":"빗자루 글에서 「빗자루를 어떻게 만드는지 아니?」로 시작하는 덩어리의 중심 내용은?","options":[{"t":"빗자루를 만드는 방법","correct":true},{"t":"칼의 모양","mis":"K2-2-u3-X07"},{"t":"손가락의 굵기","mis":"K2-2-u3-X07"}],"explanation":["만드는 방법이에요.","지도서 145쪽이에요.","작은 내용은 빼요."],"asset":{"type":"passage","lines":["빗자루는 먼지나 쓰레기를 쓸어 모으는 청소 도구예요.","수수·갈대·댑싸리·대나무 같은 것을 묶어 만들어요.","먼저 줄기를 소금물에 삶아 그늘에 말리고, 나락·꽃가루를 긁어내요.","줄기를 가지런히 묶은 뒤 끝을 가지런히 잘라요.","재료나 생김새에 따라 이름이 달라요.","싸리비(싸리) · 장목비(수수) · 갈목비(갈대 이삭)","대장 비(대나무 손잡이) · 솔비(솔가지) · 꽃비(수 놓은 방비)","옛날에는 빗자루로 인형 놀이도 했어요."],"title":"『국어』 78~80쪽 「빗자루」(윤혜신) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
