INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#18','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C8',3,'error','auto','「긴 소매 옷은 두깨가 두껍고, 반소매 옷은 두께가 얇고 소매가 짧습니다.」
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#19','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C5',3,'mc','auto','『국어활동』 35쪽 「도, 개, 걸, 윷, 모의 말뜻」의 중심 내용은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":19,"concept":"K2-2-u3-C5","difficulty":3,"kind":"mc","stem":"『국어활동』 35쪽 「도, 개, 걸, 윷, 모의 말뜻」의 중심 내용은?","options":[{"t":"도·개·걸·윷·모는 평평한 부분의 개수로 정해지고, 동물을 가리키는 옛말에서 이름을 따왔다","correct":true},{"t":"윷놀이는 겨울에만 한다","mis":"K2-2-u3-X04"},{"t":"모가 나오면 무조건 이긴다","mis":"K2-2-u3-X04"}],"explanation":["이름과 뜻이에요.","국어활동 35쪽이에요.","글에 있는 내용이에요."],"asset":{"type":"passage","lines":["윷놀이에서는 윷가락 네 개를 던져요.","평평한 부분이 몇 개 나오느냐에 따라 도·개·걸·윷·모가 정해져요.","도: 평평한 부분이 한 개 — 돼지를 가리키는 옛말","걸: 평평한 부분이 세 개 — 양을 가리키는 옛말","모: 평평한 부분이 하나도 안 나올 때 — 말의 방언"],"title":"『국어활동』 34~35쪽 「도, 개, 걸, 윷, 모의 말뜻」 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#20','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C4',3,'mc','auto','지도서 161쪽 — 중요한 문장에 밑줄을 그은 뒤 꼭 함께 해야 하는 것은?',ARRAY['K2-2-u3-X05']::text[],false,'{"seq":20,"concept":"K2-2-u3-C4","difficulty":3,"kind":"mc","stem":"지도서 161쪽 — 중요한 문장에 밑줄을 그은 뒤 꼭 함께 해야 하는 것은?","options":[{"t":"그 문장이 중요하다고 생각한 까닭을 말해요","correct":true},{"t":"모든 문장에 밑줄을 더 그어요","mis":"K2-2-u3-X05"},{"t":"첫 문장을 외워요","mis":"K2-2-u3-X05"}],"explanation":["까닭을 말해요.","지도서 160쪽이에요.","친구와 견주어요."],"asset":{"type":"passage","lines":["처음에 사람들은 어떻게, 왜 음악을 만들기 시작했을까요?","최초의 악기라고 할 수 있는 것은 사람의 목소리예요.","오랫동안 부모는 부드러운 목소리로 아기를 재웠어요.","사람들은 함께 노래하며 같은 무리라는 것을 느꼈어요.","같은 노래를 함께 부르면 서로 친구로 이어지는 것 같아요."],"title":"지도서 161쪽 평가 자료 「최초의 악기는 무엇일까요」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#21','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C9',3,'mc','auto','지도서 163쪽 — ① 「기대지 마시오」 표지판의 모양을 설명한 것으로 알맞은 것은?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":21,"concept":"K2-2-u3-C9","difficulty":3,"kind":"mc","stem":"지도서 163쪽 — ① 「기대지 마시오」 표지판의 모양을 설명한 것으로 알맞은 것은?","options":[{"t":"빨간 동그라미 안에 기대는 사람이 그려져 있고 빗금이 쳐 있어요","correct":true},{"t":"초록색 네모 안에 문이 있어요","mis":"K2-2-u3-X04"},{"t":"아무 그림도 없어요","mis":"K2-2-u3-X04"}],"explanation":["모양도 특징이에요.","지도서 163쪽이에요.","세 가지를 써요."],"asset":{"type":"scene","icon":"🚫🧍 🚫🏃 🟩🚪","text":"① 기대지 마시오 ② 뛰지 마시오 ③ 비상구 — 지도서 163쪽 표지판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#22','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C5',3,'mc','auto','『국어활동』 35쪽 — 「걸」은 무엇을 가리키는 옛말에서 이름을 따왔나요?',ARRAY['K2-2-u3-X04']::text[],false,'{"seq":22,"concept":"K2-2-u3-C5","difficulty":3,"kind":"mc","stem":"『국어활동』 35쪽 — 「걸」은 무엇을 가리키는 옛말에서 이름을 따왔나요?","options":[{"t":"양","correct":true},{"t":"돼지","mis":"K2-2-u3-X04"},{"t":"말","mis":"K2-2-u3-X04"}],"explanation":["양이에요.","국어활동 35쪽이에요.","셋의 끗수예요."],"asset":{"type":"passage","lines":["윷놀이에서는 윷가락 네 개를 던져요.","평평한 부분이 몇 개 나오느냐에 따라 도·개·걸·윷·모가 정해져요.","도: 평평한 부분이 한 개 — 돼지를 가리키는 옛말","걸: 평평한 부분이 세 개 — 양을 가리키는 옛말","모: 평평한 부분이 하나도 안 나올 때 — 말의 방언"],"title":"『국어활동』 34~35쪽 「도, 개, 걸, 윷, 모의 말뜻」 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#23','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C10',4,'sa','auto','놀이를 설명하는 글에 쓰는, 놀이에 필요한 물건을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u3-C10","difficulty":4,"kind":"sa","stem":"놀이를 설명하는 글에 쓰는, 놀이에 필요한 물건을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["준비물"],"explanation":["준비물이에요.","92쪽 보기예요.","미리 챙겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#24','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C3',4,'essay','teacher','「진심으로 사과하는 법을 알아 둬」에서 배운 대로, 약속 시간에 늦은 내가 친구에게 하는 사과의 말을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u3-C3","difficulty":4,"kind":"essay","stem":"「진심으로 사과하는 법을 알아 둬」에서 배운 대로, 약속 시간에 늦은 내가 친구에게 하는 사과의 말을 쓰세요.","answer_guide":{"answer":"예: 늦어서 정말 미안해. 시간을 잘못 봤어. 다음부터는 미리 나올게. 내 사과를 받아 줄래?","scoring_points":["미안한 까닭이 있어요","약속이 있어요","변명하지 않았어요"]},"explanation":["까닭과 약속이요.","정중하게 물어요.","74~75쪽이에요."],"asset":{"type":"passage","lines":["잘못했을 때는 상대에게 꼭 사과해야 해요.","마음속으로만 생각하면 상대는 알 수 없어요.","왜 미안한지 말하고, 다시는 그러지 않겠다고 약속해요.","받아 줄지는 상처받은 상대가 정해요.","그래서 「내 사과를 받아 줄래?」 하고 정중하게 물어봐요.","상대 잘못을 따지거나 「하지만…….」 하고 변명하지 않아요.","깨끗하게 잘못을 인정하고 진심으로 사과해요."],"title":"『국어』 74~75쪽 「진심으로 사과하는 법을 알아 둬」(박현숙) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u3_review_d#25','kor',2,2,'u3','','g2_2_kor_u3_review_d','unit_review','K2-2-u3-C10',4,'essay','teacher','아는 놀이 하나를 골라 친구가 따라 할 수 있게 놀이 방법을 차례대로 쓰세요. 숫자로 차례를 나타내세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u3-C10","difficulty":4,"kind":"essay","stem":"아는 놀이 하나를 골라 친구가 따라 할 수 있게 놀이 방법을 차례대로 쓰세요. 숫자로 차례를 나타내세요.","answer_guide":{"answer":"예: 놀이 이름: 가위바위보 계단 오르기 / ① 두 사람이 계단 아래에 서요. ② 가위바위보를 해요. ③ 이긴 사람이 한 칸 올라가요. ④ 먼저 꼭대기에 닿으면 이겨요.","scoring_points":["놀이 이름이 있어요","차례가 숫자로 나타나요","친구가 따라 할 수 있어요"]},"explanation":["차례대로 써요.","숫자를 붙여요.","92쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
